import re
import os


def task_func(request):
    if not isinstance(request, str):
        return "HTTP/1.1 400 Bad Request\n\nInvalid request"

    match = re.match(
        r"^GET[ \t]+(/[^\s?]*)[ \t]+HTTP/1\.1(?:\r?\n|$)",
        request,
    )
    if not match:
        return "HTTP/1.1 400 Bad Request\n\nInvalid request"

    requested_path = match.group(1).lstrip("/")
    if not requested_path:
        return "HTTP/1.1 404 Not Found\n\nFile not found"

    server_directory = os.path.realpath(os.getcwd())
    file_path = os.path.realpath(
        os.path.join(server_directory, requested_path)
    )

    try:
        if os.path.commonpath((server_directory, file_path)) != server_directory:
            return "HTTP/1.1 400 Bad Request\n\nInvalid path"
    except ValueError:
        return "HTTP/1.1 400 Bad Request\n\nInvalid path"

    if not os.path.isfile(file_path):
        return "HTTP/1.1 404 Not Found\n\nFile not found"

    try:
        with open(file_path, "r", encoding="utf-8") as file:
            content = file.read()
    except (OSError, UnicodeDecodeError):
        return "HTTP/1.1 404 Not Found\n\nFile not found"

    content_length = len(content.encode("utf-8"))
    return (
        "HTTP/1.1 200 OK\n"
        f"Content-Length: {content_length}\n"
        "\n"
        f"{content}"
    )

