import numpy as np
from scipy.stats import mode


def task_func(list_of_lists):
    arrays = [np.asarray(values).ravel() for values in list_of_lists]

    if not arrays or all(array.size == 0 for array in arrays):
        raise ValueError("Cannot compute the mode of an empty list.")

    merged = np.concatenate(arrays)
    result = mode(merged, axis=None, keepdims=False)

    return np.array(result.mode), int(result.count)

import numpy as np
from scipy import stats


def task_func(df, column, alpha):
    values = np.asarray(df[column].dropna(), dtype=float)

    if values.size < 3 or not np.all(np.isfinite(values)):
        return False

    if np.all(values == values[0]):
        return False

    _, p_value = stats.shapiro(values)
    return bool(p_value > alpha)

