def task_func(url, column_name, csv_file_path):
    download_succeeded = False

    try:
        urllib.request.urlretrieve(url, csv_file_path)
        download_succeeded = True

        with open(csv_file_path, "r", encoding="utf-8", newline="") as csv_file:
            reader = csv.DictReader(csv_file)

            if column_name not in (reader.fieldnames or []):
                raise ValueError(
                    f"The provided column_name '{column_name}' does not exist "
                    "in the CSV file."
                )

            counts = collections.Counter(
                row[column_name] for row in reader
            )
            return dict(counts)
    finally:
        if download_succeeded and os.path.exists(csv_file_path):
            os.remove(csv_file_path)

