import numpy as np
import ast


def task_func(csv_file):
    df = pd.read_csv(csv_file)

    required_columns = {"email", "list"}
    missing_columns = required_columns - set(df.columns)
    if missing_columns:
        raise ValueError(
            f"Missing required columns: {sorted(missing_columns)}"
        )

    def parse_list(value):
        try:
            values = ast.literal_eval(value)
        except (ValueError, SyntaxError, TypeError) as exc:
            raise ValueError(f"Invalid list value: {value!r}") from exc

        if not isinstance(values, list):
            raise ValueError(
                f"Expected a list, got {type(values).__name__}"
            )

        return values

    result = df[["email", "list"]].copy()
    result["list"] = result["list"].apply(parse_list)
    result["sum"] = result["list"].apply(np.sum)
    result["mean"] = result["list"].apply(
        lambda values: np.mean(values) if values else np.nan
    )
    result["std"] = result["list"].apply(
        lambda values: np.std(values) if values else np.nan
    )

    histogram = sns.histplot(data=result, x="mean")
    return result[["email", "list", "sum", "mean", "std"]], histogram

