# Constants
MIN_PERCENTAGE = 0.75


def task_func(data, cols, percentage):
    if not MIN_PERCENTAGE <= percentage <= 1:
        raise ValueError(
            f"percentage must be between {MIN_PERCENTAGE} and 1"
        )

    cols = list(dict.fromkeys(cols))
    missing_cols = [col for col in cols if col not in data.columns]
    if missing_cols:
        raise KeyError(f"Columns not found in DataFrame: {missing_cols}")

    corr_combinations = []

    for col1, col2 in combinations(cols, 2):
        correlation = data[col1].corr(data[col2])

        if pd.notna(correlation) and abs(correlation) > percentage:
            corr_combinations.append((col1, col2))

    return corr_combinations

