import pandas as pd
import matplotlib.pyplot as plt


def task_func(file_path):
    try:
        path = str(file_path)
    except Exception as exc:
        raise ValueError("Invalid file path.") from exc

    if not path.lower().endswith(".csv"):
        raise ValueError("The file must have a .csv extension.")

    try:
        with open(path, "r", encoding="utf-8", newline="") as file:
            rows = [tuple(row) for row in csv.reader(file, strict=True)]
    except (OSError, UnicodeError, csv.Error) as exc:
        raise ValueError("The CSV file could not be read.") from exc

    counts = Counter(rows)
    duplicate_counts = {
        row: count for row, count in counts.items() if count > 1
    }

    duplicate_rows = list(duplicate_counts)
    max_columns = max(
        (len(row) for row in duplicate_rows),
        default=0,
    )

    dataframe = pd.DataFrame(
        [
            list(row) + [None] * (max_columns - len(row))
            for row in duplicate_rows
        ],
        columns=[
            f"column_{index + 1}"
            for index in range(max_columns)
        ],
    )

    labels = [
        tuple(
            value if value is not None else ""
            for value in row
        )
        for row in dataframe.itertuples(index=False, name=None)
    ]

    _, ax = plt.subplots()
    ax.bar(
        [str(label) for label in labels],
        list(duplicate_counts.values()),
    )
    ax.set_xlabel("Duplicate rows")
    ax.set_ylabel("Count")
    ax.set_title("Duplicate CSV Rows")

    return duplicate_counts, ax

import re
