import requests


def task_func(myString, token):
    """Extract the first URL from myString and submit it to the REST API."""

    if not isinstance(myString, str):
        raise TypeError("myString must be a string")
    if not isinstance(token, str) or not token.strip():
        raise ValueError("token must be a non-empty string")

    match = re.search(r"https?://[^\s<>\[\]{}]+", myString, re.IGNORECASE)
    if match is None:
        raise ValueError("No URL found in myString")

    url = match.group(0).rstrip(".,;:!?)]}\"'")

    response = requests.post(
        "https://example.com/api",
        headers={
            "Authorization": f"Bearer {token}",
            "Content-Type": "application/json",
        },
        data=json.dumps({"url": url}),
        timeout=30,
    )
    response.raise_for_status()
    return response.json()

