import numpy as np
import pandas as pd
from sklearn.preprocessing import StandardScaler


def task_func(P, T):
    P = np.asarray(P)
    T = np.asarray(T)

    if P.ndim != 2:
        raise ValueError("P must be a 2D matrix.")
    if T.ndim != 3:
        raise ValueError("T must be a 3D tensor.")
    if P.shape[1] != T.shape[0]:
        raise ValueError(
            "Incompatible shapes: P.shape[1] must equal T.shape[0]."
        )

    result = np.tensordot(P, T, axes=([1], [0]))
    flattened = result.reshape(result.shape[0], -1)

    normalized = StandardScaler().fit_transform(flattened)
    columns = [f"feature_{i}" for i in range(flattened.shape[1])]

    return pd.DataFrame(normalized, columns=columns)

