# Constants
CSV_FILE_PATH = 'scraped_data.csv'


def task_func(url):
    if not isinstance(url, str) or not url.strip():
        raise ValueError("url must be a non-empty string")

    response = urllib.request.urlopen(url, timeout=30)
    try:
        data = response.read()
        charset = None

        headers = getattr(response, "headers", None)
        if headers is not None:
            get_charset = getattr(headers, "get_content_charset", None)
            if callable(get_charset):
                charset = get_charset()

        try:
            html = data.decode(charset or "utf-8")
        except (LookupError, UnicodeDecodeError):
            html = data.decode("utf-8", errors="replace")
    finally:
        close = getattr(response, "close", None)
        if callable(close):
            close()

    soup = BeautifulSoup(html, "html.parser")

    for element in soup(["script", "style", "noscript", "template"]):
        element.decompose()

    tables = soup.find_all("table")
    headers = []
    rows = []

    for table_index, table in enumerate(tables):
        table_rows = []

        for table_row in table.find_all("tr"):
            cells = table_row.find_all(["th", "td"])
            values = [
                " ".join(cell.get_text(" ", strip=True).split())
                for cell in cells
            ]
            if values and any(values):
                table_rows.append((values, bool(table_row.find("th"))))

        if not table_rows:
            continue

        if table_index == 0 and table_rows[0][1]:
            headers = table_rows[0][0]
            rows.extend(row[0] for row in table_rows[1:])
        else:
            rows.extend(row[0] for row in table_rows)

    if rows:
        column_count = max(
            len(headers),
            max(len(row) for row in rows),
        )

        if not headers:
            headers = [
                f"column_{index}"
                for index in range(1, column_count + 1)
            ]
        else:
            headers.extend(
                f"column_{index}"
                for index in range(len(headers) + 1, column_count + 1)
            )

        normalized_rows = [
            row[:column_count] + [""] * (column_count - len(row))
            for row in rows
        ]
    else:
        content = " ".join(soup.get_text(" ", strip=True).split())
        headers = ["content"]
        normalized_rows = [[content]] if content else []

    output_directory = os.path.dirname(CSV_FILE_PATH)
    if output_directory:
        os.makedirs(output_directory, exist_ok=True)

    with open(CSV_FILE_PATH, "w", newline="", encoding="utf-8") as csv_file:
        writer = csv.writer(csv_file)
        writer.writerow(headers)
        writer.writerows(normalized_rows)

    return CSV_FILE_PATH

