import base64


def task_func(raw_string, filename, output_dir):
    try:
        decoded = base64.b64decode(raw_string, validate=True).decode("utf-8")
    except (ValueError, TypeError, UnicodeDecodeError) as exc:
        raise ValueError("Invalid Base64-encoded UTF-8 data") from exc

    try:
        data = json.loads(decoded)
    except json.JSONDecodeError as exc:
        raise ValueError("Invalid JSON data") from exc

    if not isinstance(filename, str) or not filename:
        raise ValueError("Filename must be a non-empty string")

    output_dir_abs = os.path.abspath(output_dir)
    file_path = os.path.abspath(os.path.join(output_dir_abs, filename))

    try:
        if os.path.commonpath((output_dir_abs, file_path)) != output_dir_abs:
            raise ValueError("Filename must remain inside output_dir")
    except ValueError as exc:
        raise ValueError("Invalid filename path") from exc

    os.makedirs(output_dir_abs, exist_ok=True)

    with open(file_path, "w", newline="", encoding="utf-8") as csv_file:
        writer = csv.writer(csv_file)

        if isinstance(data, list) and all(isinstance(item, dict) for item in data):
            headers = []
            for item in data:
                for key in item:
                    if key not in headers:
                        headers.append(key)

            if headers:
                writer.writerow(headers)
                for item in data:
                    writer.writerow([item.get(key, "") for key in headers])

        elif isinstance(data, dict):
            writer.writerow(["key", "value"])
            for key, value in data.items():
                writer.writerow([key, value])

        elif isinstance(data, list):
            writer.writerow(["data"])
            for value in data:
                writer.writerow([value])

        else:
            writer.writerow(["data"])
            writer.writerow([data])

    return file_path

import pandas as pd
import re
import random


def task_func(s: str, seed: int = 0) -> pd.DataFrame:
    columns = ["ID", "Quantity", "Code", "Price", "Product", "Description"]
    products = ["Apple", "Banana", "Orange", "Pear", "Grape"]

    rng = random.Random(seed)
    code_to_product = {}
    records = []

    for line_number, line in enumerate(s.splitlines(), start=1):
        if not line.strip():
            continue

        parts = re.split(r"\s+", line.strip(), maxsplit=4)
        if len(parts) != 5:
            raise ValueError(
                f"Line {line_number} must contain ID, quantity, code, price, "
                "and description."
            )

        item_id, quantity, code, price, description = (
            part.rstrip() for part in parts
        )

        try:
            quantity = int(quantity)
            price = int(price)
        except ValueError as exc:
            raise ValueError(
                f"Line {line_number} has invalid quantity or price."
            ) from exc

        if code not in code_to_product:
            code_to_product[code] = rng.choice(products)

        records.append(
            {
                "ID": item_id,
                "Quantity": quantity,
                "Code": code,
                "Price": price,
                "Product": code_to_product[code],
                "Description": description,
            }
        )

    return pd.DataFrame(records, columns=columns)

import itertools
import math
from pandas import Series


def task_func(elements, subset_size, top_n=2):
    if subset_size < 0:
        raise ValueError("subset_size must be non-negative")
    if top_n < 0:
        raise ValueError("top_n must be non-negative")

    if subset_size == 0 or subset_size > len(elements):
        return 1, Series(dtype=int)

    subset_sums = [
        sum(subset)
        for subset in itertools.combinations(elements, subset_size)
    ]

    product_of_sums = math.prod(subset_sums)
    top_sums = Series(sorted(subset_sums, reverse=True)[:top_n])

    return product_of_sums, top_sums

