import time


def task_func(process_name: str) -> int:
    if not process_name or not process_name.strip():
        time.sleep(1)
        return 0

    current_pid = os.getpid()
    matching_pids = set()

    try:
        if os.name == "nt":
            result = subprocess.run(
                ["tasklist", "/FO", "CSV", "/NH"],
                capture_output=True,
                text=True,
                check=False,
            )

            for line in result.stdout.splitlines():
                fields = line.strip().split('","')
                if len(fields) < 2:
                    continue

                image_name = fields[0].lstrip('"')
                pid_text = fields[1].rstrip('"')

                if image_name.lower() == process_name.lower():
                    try:
                        pid = int(pid_text)
                    except ValueError:
                        continue

                    if pid != current_pid:
                        matching_pids.add(pid)
        else:
            result = subprocess.run(
                ["ps", "-eo", "pid=,comm="],
                capture_output=True,
                text=True,
                check=False,
            )

            for line in result.stdout.splitlines():
                parts = line.strip().split(None, 1)
                if len(parts) != 2:
                    continue

                try:
                    pid = int(parts[0])
                except ValueError:
                    continue

                if pid != current_pid and parts[1] == process_name:
                    matching_pids.add(pid)
    except OSError:
        time.sleep(1)
        return 0

    stopped = 0

    for pid in matching_pids:
        try:
            if os.name == "nt":
                result = subprocess.run(
                    ["taskkill", "/PID", str(pid), "/T", "/F"],
                    capture_output=True,
                    text=True,
                    check=False,
                )
                if result.returncode == 0:
                    stopped += 1
            else:
                os.kill(pid, signal.SIGTERM)
                stopped += 1
        except (OSError, subprocess.SubprocessError):
            continue

    time.sleep(1)
    return stopped

