import os
import shutil

# Constants
BACKUP_DIR = '/tmp/backup'


def get_unique_backup_dir():
    return "/fake/backup/path"


def task_func(directory):
    """
    Back up all contents of a directory and remove them after successful backup.

    Returns:
        tuple: The backup directory path and a list of encountered errors.
    """
    backup_dir = get_unique_backup_dir()
    errors = []

    if not isinstance(directory, (str, bytes, os.PathLike)):
        return backup_dir, [TypeError("directory must be a path-like object")]

    try:
        if not os.path.exists(directory):
            return backup_dir, [FileNotFoundError(directory)]

        if not os.path.isdir(directory):
            return backup_dir, [NotADirectoryError(directory)]

        os.makedirs(backup_dir, exist_ok=False)

        with os.scandir(directory) as entries:
            for entry in entries:
                source_path = entry.path
                destination_path = os.path.join(backup_dir, entry.name)

                try:
                    if entry.is_dir(follow_symlinks=False):
                        shutil.copytree(
                            source_path,
                            destination_path,
                            symlinks=True,
                        )
                        shutil.rmtree(source_path)
                    else:
                        shutil.copy2(
                            source_path,
                            destination_path,
                            follow_symlinks=False,
                        )
                        os.unlink(source_path)
                except Exception as exc:
                    errors.append(exc)

    except Exception as exc:
        errors.append(exc)

    return backup_dir, errors

import subprocess
import os
import shutil
from glob import glob


def task_func(src_folder, dst_folder):
    if not os.path.isdir(src_folder):
        return {
            "success": False,
            "message": "Source folder does not exist or is not a directory.",
            "failed_files": [],
        }

    if os.path.exists(dst_folder) and not os.path.isdir(dst_folder):
        return {
            "success": False,
            "message": "Destination path exists but is not a directory.",
            "failed_files": [],
        }

    try:
        os.makedirs(dst_folder, exist_ok=True)
    except OSError as exc:
        return {
            "success": False,
            "message": f"Could not create destination folder: {exc}",
            "failed_files": [],
        }

    source_files = sorted(
        path for path in glob(os.path.join(src_folder, "*"))
        if os.path.isfile(path)
    )

    if not source_files:
        return {
            "success": True,
            "message": "No files found to compress.",
            "failed_files": [],
        }

    failed_files = []
    processes = []

    for source_file in source_files:
        filename = os.path.basename(source_file)
        try:
            process = subprocess.Popen(
                ["gzip", source_file],
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
            )
            processes.append((process, source_file, filename))
        except OSError:
            failed_files.append(filename)

    same_destination = os.path.abspath(src_folder) == os.path.abspath(dst_folder)

    for process, source_file, filename in processes:
        try:
            return_code = process.wait()
        except OSError:
            return_code = 1

        compressed_file = source_file + ".gz"

        if return_code != 0 or not os.path.isfile(compressed_file):
            if filename not in failed_files:
                failed_files.append(filename)
            continue

        if same_destination:
            continue

        try:
            shutil.move(
                compressed_file,
                os.path.join(dst_folder, os.path.basename(compressed_file)),
            )
        except OSError:
            if filename not in failed_files:
                failed_files.append(filename)

    if failed_files:
        return {
            "success": False,
            "message": f"{len(failed_files)} file(s) failed to compress or move.",
            "failed_files": failed_files,
        }

    return {
        "success": True,
        "message": "All files were compressed and moved successfully.",
        "failed_files": [],
    }

