import numpy as np
import random


def task_func(MIN_WORDS, MAX_WORDS, WORDS_POOL):
    if isinstance(MIN_WORDS, bool) or not isinstance(MIN_WORDS, (int, np.integer)):
        raise ValueError("MIN_WORDS must be an integer")
    if isinstance(MAX_WORDS, bool) or not isinstance(MAX_WORDS, (int, np.integer)):
        raise ValueError("MAX_WORDS must be an integer")

    MIN_WORDS = int(MIN_WORDS)
    MAX_WORDS = int(MAX_WORDS)

    if MIN_WORDS < 1 or MIN_WORDS > MAX_WORDS:
        raise ValueError("Invalid word count range")
    if isinstance(WORDS_POOL, (str, bytes)):
        raise ValueError("WORDS_POOL must be an iterable of words")

    try:
        pool = list(WORDS_POOL)
    except TypeError as exc:
        raise ValueError("WORDS_POOL must be an iterable of words") from exc

    if not pool or any(
        not isinstance(word, str) or not word or any(char.isspace() for char in word)
        for word in pool
    ):
        raise ValueError("WORDS_POOL must contain non-empty single-word strings")

    length = random.randint(MIN_WORDS, MAX_WORDS)
    half_length = (length + 1) // 2
    first_half = [random.choice(pool) for _ in range(half_length)]
    words = first_half + first_half[: length // 2][::-1]

    if not (MIN_WORDS <= len(words) <= MAX_WORDS):
        raise RuntimeError("Generated sentence length is out of range")
    if words != words[::-1]:
        raise RuntimeError("Generated sentence is not a palindrome")

    return " ".join(words)

