import matplotlib.pyplot as plt


def task_func(data_file_path: str):
    try:
        with open(data_file_path, "r", encoding="utf-8") as file:
            first_line = next((line for line in file if line.strip()), "")
    except (OSError, UnicodeError) as exc:
        raise ValueError(f"Unable to read CSV file: {exc}") from exc

    if not first_line:
        raise ValueError("The CSV file is empty.")

    delimiter = ";" if ";" in first_line else ","

    try:
        data = pd.read_csv(data_file_path, sep=delimiter)
    except pd.errors.EmptyDataError as exc:
        raise ValueError("The CSV file is empty.") from exc

    if len(data.columns) == 0:
        raise ValueError("The CSV file contains no columns.")

    for column in data.columns:
        if not pd.api.types.is_numeric_dtype(data[column]):
            values = (
                data[column]
                .astype("string")
                .str.strip()
                .str.replace(",", ".", regex=False)
            )
            data[column] = pd.to_numeric(values, errors="coerce")

    means = data.mean()
    std_devs = data.std()

    axes = []
    for column in data.columns:
        _, ax = plt.subplots()
        data[column].dropna().plot.hist(ax=ax)
        ax.set_title(f"Histogram of {column}")
        ax.set_xlabel(str(column))
        axes.append(ax)

    result_columns = ["F-value", "P-value"]

    if len(data.columns) < 2:
        anova_results = pd.DataFrame(columns=result_columns)
    else:
        results = {}

        for first_index in range(len(data.columns)):
            for second_index in range(first_index + 1, len(data.columns)):
                first = data.iloc[:, first_index].dropna()
                second = data.iloc[:, second_index].dropna()

                pair_name = (
                    f"{data.columns[first_index]} vs "
                    f"{data.columns[second_index]}"
                )

                if len(first) < 2 or len(second) < 2:
                    f_value = float("nan")
                    p_value = float("nan")
                else:
                    f_value, p_value = f_oneway(first, second)

                results[pair_name] = {
                    "F-value": f_value,
                    "P-value": p_value,
                }

        anova_results = pd.DataFrame.from_dict(results, orient="index")
        anova_results = anova_results.reindex(columns=result_columns)

    return means, std_devs, axes, anova_results

