import json
import re
import pandas as pd

def task_func(json_str):
    if not isinstance(json_str, str) or not json_str.strip():
        return pd.DataFrame()

    try:
        data = json.loads(json_str)
    except (json.JSONDecodeError, TypeError):
        return pd.DataFrame()

    if not isinstance(data, dict) or not data:
        return pd.DataFrame()

    number_pattern = re.compile(
        r"[-+]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][-+]?\d+)?"
    )
    full_number_pattern = re.compile(
        rf"^\s*({number_pattern.pattern})\s*$"
    )

    def is_number(value):
        return isinstance(value, (int, float)) and not isinstance(value, bool)

    def normalize_value(value):
        if is_number(value):
            return float(value * 2)

        if isinstance(value, list):
            normalized = []
            for item in value:
                if is_number(item):
                    normalized.append(float(item * 2))
                elif isinstance(item, str):
                    match = full_number_pattern.match(item)
                    if match:
                        normalized.append(float(match.group(1)) * 2)
                    else:
                        normalized.append(item)
                else:
                    normalized.append(item)
            return normalized

        if isinstance(value, str):
            matches = number_pattern.findall(value)
            if matches:
                return [float(number) * 2 for number in matches]
            return value

        return value

    normalized_data = {
        key: normalize_value(value)
        for key, value in data.items()
    }

    try:
        return pd.DataFrame(normalized_data)
    except (ValueError, TypeError):
        return pd.DataFrame()

