        if content.endswith("\n"):
            content = content[:-1]
            if content.endswith("\r"):
                content = content[:-1]
        elif content.endswith("\r"):
            content = content[:-1]

        if status == "  ":
            differences.append(
                {
                    "Line Number": line_number1,
                    "Status": " ",
                    "Content": content,
                }
            )
            line_number1 += 1
            line_number2 += 1
        elif status == "- ":
            differences.append(
                {
                    "Line Number": line_number1,
                    "Status": "-",
                    "Content": content,
                }
            )
            line_number1 += 1
        elif status == "+ ":
            differences.append(
                {
                    "Line Number": line_number2,
                    "Status": "+",
                    "Content": content,
                }
            )
            line_number2 += 1

    return pd.DataFrame(
        differences,
        columns=["Line Number", "Status", "Content"],
    )

