import matplotlib.pyplot as plt


def task_func(input_file):
    with open(input_file, "r", encoding="utf-8") as file:
        data = json.load(file)

    if not isinstance(data, list):
        raise ValueError("The JSON file must contain a list of dictionaries.")

    values_by_key = defaultdict(list)

    for item in data:
        if not isinstance(item, dict):
            raise ValueError("Every item in the JSON list must be a dictionary.")

        for key, value in item.items():
            if isinstance(value, bool) or not isinstance(value, (int, float)):
                raise TypeError(
                    f"Value for key {key!r} must be a numeric value."
                )
            values_by_key[key].append(value)

    result = {}
    plots = []

    for key, values in values_by_key.items():
        try:
            numeric_values = np.asarray(values, dtype=float)
        except (TypeError, ValueError, OverflowError) as exc:
            raise ValueError(
                f"Values for key {key!r} cannot be converted to finite numbers."
            ) from exc

        if not np.all(np.isfinite(numeric_values)):
            raise ValueError(f"Values for key {key!r} must be finite.")

        mean_value = float(np.mean(numeric_values))
        median_value = float(np.median(numeric_values))

        result[key] = {
            "mean": mean_value,
            "median": median_value,
        }

        _, ax = plt.subplots()
        ax.bar(["mean", "median"], [mean_value, median_value])
        ax.set_title(f"Mean and Median for {key}")
        ax.set_ylabel("Value")
        plots.append(ax)

    return result, plots

