import socket
from ipaddress import IPv4Network
from threading import Thread


def task_func(ip_range, port):
    network = IPv4Network(ip_range, strict=False)
    results = {}

    def scan_ip(ip):
        address = str(ip)
        sock = None
        status = False

        try:
            sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            sock.settimeout(1.0)
            status = sock.connect_ex((address, port)) == 0
        except (OSError, TypeError, ValueError):
            status = False
        finally:
            if sock is not None:
                try:
                    sock.close()
                except OSError:
                    pass

        results[address] = status

    threads = [
        Thread(target=scan_ip, args=(ip,))
        for ip in network
    ]

    for thread in threads:
        thread.start()

    for thread in threads:
        thread.join()

    return results

