import cgi
import http.server
import json

SUCCESS_RESPONSE = {
    'status': 'success',
    'message': 'Data received successfully.'
}
ERROR_RESPONSE = {
    'status': 'error',
    'message': 'Invalid data received.'
}


def task_func():
    class RequestHandler(http.server.BaseHTTPRequestHandler):
        def _send_response(self, status_code, body, content_type):
            if isinstance(body, str):
                body = body.encode('utf-8')

            self.send_response(status_code)
            self.send_header('Content-Type', content_type)
            self.send_header('Content-Length', str(len(body)))
            self.end_headers()
            self.wfile.write(body)

        def do_POST(self):
            content_type = self.headers.get('Content-Type', '')
            media_type, _ = cgi.parse_header(content_type)

            if media_type.lower() != 'application/json':
                self._send_response(
                    400,
                    'Content-Type header is not application/json',
                    'text/plain; charset=utf-8'
                )
                return

            try:
                content_length = int(self.headers.get('Content-Length', '0'))
                if content_length < 0:
                    raise ValueError

                body = self.rfile.read(content_length)
                request_data = json.loads(body.decode('utf-8'))
            except (ValueError, UnicodeDecodeError, json.JSONDecodeError):
                self._send_response(
                    400,
                    'Invalid JSON',
                    'text/plain; charset=utf-8'
                )
                return

            if not isinstance(request_data, dict) or 'data' not in request_data:
                self._send_response(
                    400,
                    'No data key in request',
                    'text/plain; charset=utf-8'
                )
                return

            self._send_response(
                200,
                json.dumps(SUCCESS_RESPONSE).encode('utf-8'),
                'application/json'
            )

    return RequestHandler

