# Constants
WORDS = ['the', 'be', 'to', 'of', 'and', 'a', 'in', 'that', 'have', 'I']


def task_func(sentences_dict, word_keys):
    """Count selected words and return a bar chart Axes object."""
    if not isinstance(sentences_dict, Mapping):
        raise TypeError("sentences_dict must be a mapping")

    if word_keys is None:
        word_keys = WORDS
    elif isinstance(word_keys, str):
        word_keys = [word_keys]
    else:
        try:
            word_keys = list(word_keys)
        except TypeError as exc:
            raise TypeError("word_keys must be iterable") from exc

    normalized_keys = [str(word).casefold() for word in word_keys]
    counter = collections.Counter()

    for value in sentences_dict.values():
        if isinstance(value, str):
            sentences = [value]
        elif isinstance(value, Iterable):
            sentences = value
        else:
            continue

        for sentence in sentences:
            if not isinstance(sentence, str):
                continue

            tokens = re.findall(
                r"[^\W_]+(?:['’][^\W_]+)*",
                sentence.casefold(),
                flags=re.UNICODE,
            )
            counter.update(tokens)

    data = pd.DataFrame(
        {
            "word": word_keys,
            "frequency": [
                counter.get(word, 0) for word in normalized_keys
            ],
        }
    )

    ax = data.plot(
        x="word",
        y="frequency",
        kind="bar",
        legend=False,
        title="Word Frequencies",
    )
    ax.set_xlabel("Word")
    ax.set_ylabel("Frequency")
    plt.tight_layout()

    return ax

import pandas as pd
