def task_func(df, items=None, locations=None):
    if not isinstance(df, pd.DataFrame):
        raise ValueError("df must be a pandas DataFrame")

    required_columns = {"Item", "Location"}
    missing = required_columns.difference(df.columns)
    if missing:
        raise ValueError(
            f"Missing required columns: {', '.join(sorted(missing))}"
        )

    def normalize_selection(value, column):
        if value is None:
            return (
                df[column]
                .dropna()
                .drop_duplicates()
                .tolist()
            )
        if isinstance(value, str):
            return [value]
        return list(dict.fromkeys(value))

    selected_items = normalize_selection(items, "Item")
    selected_locations = normalize_selection(locations, "Location")

    filtered = df[
        df["Item"].isin(selected_items)
        & df["Location"].isin(selected_locations)
    ]

    counts = pd.crosstab(filtered["Item"], filtered["Location"]).reindex(
        index=selected_items,
        columns=selected_locations,
        fill_value=0,
    )

    fig, ax = plt.subplots(figsize=(8, 5))

    if selected_items and selected_locations:
        width = 0.8 / len(selected_locations)
        positions = range(len(selected_items))

        for index, location in enumerate(selected_locations):
            offsets = [
                position - 0.4 + width * (index + 0.5)
                for position in positions
            ]
            ax.bar(
                offsets,
                counts[location].tolist(),
                width=width,
                label=str(location),
            )

        ax.set_xticks(list(positions))
        ax.set_xticklabels([str(item) for item in selected_items])
