            output = output.decode(errors="replace")

        cpu_usage = None

        if system == "Windows":
            for line in output.splitlines():
                try:
                    cpu_usage = float(line.strip())
                    break
                except ValueError:
                    continue
        else:
            for line in output.splitlines():
                parts = line.replace(",", " ").split()

                for index, part in enumerate(parts):
                    marker = part.strip().lower().rstrip(":")
                    if marker in {"id", "idle"} and index > 0:
                        try:
                            idle = float(parts[index - 1].strip().rstrip("%"))
                            cpu_usage = 100.0 - idle
                            break
                        except ValueError:
                            continue

                if cpu_usage is not None:
                    break

        if cpu_usage is None:
            raise ValueError("Unable to parse CPU usage")

        records.append(
            {
                "timestamp": time.time(),
                "cpu_usage": cpu_usage,
            }
        )

        time.sleep(interval)

    try:
        with open(LOGFILE_PATH, "w") as logfile:
            json.dump(records, logfile)
    except IOError:
        return None

    return LOGFILE_PATH

