def task_func(json_data: str, key_path: list):
    if not isinstance(json_data, str) or not json_data.strip():
        raise ValueError("JSON data is empty.")

    def reject_invalid_constant(value):
        raise ValueError(f"Invalid JSON constant: {value}")

    try:
        data = json.loads(json_data, parse_constant=reject_invalid_constant)
    except (json.JSONDecodeError, TypeError, ValueError) as exc:
        raise ValueError("JSON data is corrupted.") from exc

    current = data
    for key in key_path:
        if not isinstance(current, dict) or key not in current:
            raise KeyError(key)
        current = current[key]

    values = []

    def collect_numbers(value):
        if isinstance(value, bool):
            return
        if isinstance(value, int):
            values.append(value)
        elif isinstance(value, float):
            if np.isfinite(value):
                values.append(value)
        elif isinstance(value, dict):
            for nested_value in value.values():
                collect_numbers(nested_value)
        elif isinstance(value, list):
            for nested_value in value:
                collect_numbers(nested_value)

    collect_numbers(current)

    if not values:
        raise ValueError("No numeric data found.")

    dataframe = pd.DataFrame({"value": values})
    figure, axis = plt.subplots()
