import re
import socket


def task_func(ip_addresses: list) -> dict:
    result = {}
    ip_pattern = re.compile(r"^[0-9A-Fa-f:.]+$")

    for ip_address in ip_addresses:
        if not isinstance(ip_address, str) or not ip_pattern.fullmatch(ip_address):
            continue

        valid = False
        for family in (socket.AF_INET, socket.AF_INET6):
            try:
                socket.inet_pton(family, ip_address)
                valid = True
                break
            except (OSError, ValueError):
                continue

        if not valid:
            continue

        try:
            result[ip_address] = socket.gethostbyaddr(ip_address)[0]
        except (socket.herror, socket.gaierror, socket.timeout, OSError):
            result[ip_address] = None

    return result

