def task_func(precision=2, seed=0):
    if isinstance(precision, bool) or not isinstance(precision, int) or precision < 0:
        raise ValueError("precision must be a non-negative integer")

    np.random.seed(seed)

    while True:
        a, b, c = np.random.randint(-10, 11, size=3)
        if a != 0:
            break

    discriminant = complex(b**2 - 4 * a * c)
    sqrt_discriminant = np.sqrt(discriminant)

    root_1 = (-b + sqrt_discriminant) / (2 * a)
    root_2 = (-b - sqrt_discriminant) / (2 * a)

    def round_complex(root):
        return complex(round(root.real, precision), round(root.imag, precision))

    return round_complex(root_1), round_complex(root_2)

