def task_func(dataframe, data_pattern=DATA_PATTERN):
    """Extract numeric values from matching DataFrame cells."""
    if not isinstance(dataframe, pd.DataFrame):
        raise TypeError("dataframe must be a pandas DataFrame")

    pattern = re.compile(data_pattern)

    def extract_value(cell):
        match = pattern.search(str(cell))
        if match is None:
            return np.nan

        try:
            return float(match.group(0)[1:-1])
        except (TypeError, ValueError):
            return np.nan

    return dataframe.applymap(extract_value)

import rsa
import os
import zipfile
from base64 import b64encode


def task_func(directory):
    if not os.path.isdir(directory):
        raise ValueError(f"Invalid directory: {directory}")

    directory = os.path.abspath(directory)
    public_key, _ = rsa.newkeys(2048)

    zip_filename = "encrypted_files.zip"
    output_path = os.path.abspath(zip_filename)
    max_block_size = rsa.common.byte_size(public_key.n) - 11

    with zipfile.ZipFile(
        output_path,
        mode="w",
        compression=zipfile.ZIP_DEFLATED,
    ) as archive:
        for root, dirs, files in os.walk(directory, followlinks=False):
            dirs[:] = [
                name
                for name in dirs
                if not os.path.islink(os.path.join(root, name))
            ]

            for filename in files:
                file_path = os.path.join(root, filename)

                if os.path.islink(file_path):
                    continue
                if os.path.abspath(file_path) == output_path:
                    continue
                if not os.path.isfile(file_path):
                    continue

                with open(file_path, "rb") as source:
                    data = source.read()

                encrypted = b"".join(
                    rsa.encrypt(
                        data[index:index + max_block_size],
                        public_key,
                    )
                    for index in range(0, len(data), max_block_size)
                )

                relative_path = os.path.relpath(file_path, directory)
                archive.writestr(relative_path, b64encode(encrypted))

    return public_key, zip_filename

