def task_func(start_date='2016-01-01', periods=13, freq='WOM-2FRI', sales_data=None):
    if isinstance(periods, bool) or not isinstance(periods, (int, np.integer)):
        raise TypeError("periods must be a positive integer")
    if periods <= 0:
        raise ValueError("periods must be positive")

    try:
        dates = pd.date_range(start=start_date, periods=periods, freq=freq)
    except (TypeError, ValueError) as exc:
        raise ValueError("Invalid start_date or frequency") from exc

    if sales_data is None:
        n = len(dates)
        indices = np.arange(n, dtype=float)
        sales = 100.0 + 5.0 * indices + 10.0 * np.sin(
            2.0 * np.pi * indices / n
        )
    else:
        raw_data = np.asarray(sales_data)

        if raw_data.ndim == 0:
            raise ValueError("sales_data must be a one-dimensional series")
        if raw_data.ndim > 1:
            if 1 not in raw_data.shape:
                raise ValueError("sales_data must represent a single series")
            raw_data = raw_data.reshape(-1)

        try:
            sales = raw_data.astype(float)
        except (TypeError, ValueError) as exc:
            raise ValueError("sales_data must contain numeric values") from exc

        if sales.size == 0:
            raise ValueError("sales_data must not be empty")
        if sales.size != periods:
            raise ValueError("sales_data length must match periods")
