from numbers import Integral


def task_func(csv_file, column_name="data", pattern=r"\d+[xX]", sample_size=None, seed=42):
    df = pd.read_csv(csv_file)

    if column_name not in df.columns:
        raise KeyError(f"Column {column_name!r} not found in the CSV file.")

    if sample_size is not None:
        if isinstance(sample_size, bool) or not isinstance(sample_size, Integral):
            raise TypeError("sample_size must be a non-negative integer.")
        if sample_size < 0:
            raise ValueError("sample_size must be non-negative.")

    mask = df[column_name].astype("string").str.contains(
        pattern, regex=True, na=False
    )
    matches = df.loc[mask]

    if sample_size is None:
        return matches

    count = min(sample_size, len(matches))
    indices = random.Random(seed).sample(range(len(matches)), count)
    return matches.iloc[indices]

