import os
import re
import hashlib


def task_func(path, delimiter):
    """Split path by a literal delimiter and hash file components with SHA-256."""
    if not isinstance(path, str):
        raise TypeError("path must be a string")
    if not isinstance(delimiter, str):
        raise TypeError("delimiter must be a string")
    if not delimiter:
        raise ValueError("delimiter must not be empty")

    components = re.split(f"({re.escape(delimiter)})", path)
    result = []

    for component in components:
        file_hash = None

        if os.path.isfile(component):
            digest = hashlib.sha256()
            with open(component, "rb") as file:
                for chunk in iter(lambda: file.read(8192), b""):
                    digest.update(chunk)
            file_hash = digest.hexdigest()

        result.append((component, file_hash))

    return result

