import os


def task_func(directory: str, pattern: str = r"(?<!Distillr)\\AcroTray\.exe") -> dict:
    if not os.path.exists(directory):
        raise FileNotFoundError(directory)
    if not os.path.isdir(directory):
        raise NotADirectoryError(directory)

    regex = re.compile(pattern)
    result = {}

    def handle_walk_error(error: OSError) -> None:
        raise error

    for root, _, filenames in os.walk(directory, onerror=handle_walk_error):
        for filename in filenames:
            file_path = os.path.join(root, filename)

            if not os.path.isfile(file_path) or not regex.search(file_path):
                continue

            digest = hashlib.sha256()
            with open(file_path, "rb") as file:
                for chunk in iter(lambda: file.read(1024 * 1024), b""):
                    digest.update(chunk)

            result[file_path] = binascii.hexlify(digest.digest()).decode("ascii")

    return result

import re
import json
import requests


def task_func(data_url: str) -> list:
    try:
        response = requests.get(data_url)
        data = response.text
    except Exception:
        return "Invalid url input"

    name_pattern = re.compile(r'"name"\s*:\s*"((?:\\.|[^"\\])*)"')

    bracket_depth = 0
    depths = [0] * len(data)
    outside_string = [True] * len(data)
    in_string = False
    escaped = False

    for index, char in enumerate(data):
        depths[index] = bracket_depth
        outside_string[index] = not in_string

        if in_string:
            if escaped:
                escaped = False
            elif char == "\\":
                escaped = True
            elif char == '"':
                in_string = False
        elif char == '"':
            in_string = True
        elif char == "[":
            bracket_depth += 1
        elif char == "]":
            bracket_depth = max(0, bracket_depth - 1)

    names = []
    for match in name_pattern.finditer(data):
        start = match.start()
        if outside_string[start] and depths[start] == 0:
            try:
                names.append(json.loads(f'"{match.group(1)}"'))
            except Exception:
                names.append(match.group(1))

    return names

