# Constants
BACKUP_DIR = '/tmp/backup'


def task_func(directory):
    if not os.path.isdir(BACKUP_DIR):
        return f"Backup directory {BACKUP_DIR} does not exist. Cannot rollback update."

    directory = os.path.normpath(directory)
    backup_path = os.path.join(BACKUP_DIR, os.path.basename(directory))

    if not os.path.isdir(backup_path):
        return f"Backup for directory {directory} does not exist."

    try:
        if os.path.islink(directory) or os.path.isfile(directory):
            os.remove(directory)
        elif os.path.isdir(directory):
            shutil.rmtree(directory)

        shutil.copytree(backup_path, directory)
        return directory
    except (OSError, shutil.Error) as error:
        return f"Failed to rollback directory {directory}: {error}"

