import numpy as np
import pandas as pd


def task_func(
    products,
    n_samples=100,
    sales_lower=50,
    sales_upper=200,
    profit_margin_min=0.1,
    profit_margin_max=0.5,
    random_seed=42,
):
    if not isinstance(products, list) or not all(
        isinstance(product, str) for product in products
    ):
        raise TypeError("products must be a list of strings")

    if isinstance(n_samples, bool) or not isinstance(n_samples, numbers.Integral):
        raise ValueError("n_samples must be a positive integer")
    if n_samples <= 0:
        raise ValueError("n_samples must be a positive integer")

    numeric_values = (
        sales_lower,
        sales_upper,
        profit_margin_min,
        profit_margin_max,
    )
    if any(
        isinstance(value, bool) or not isinstance(value, numbers.Real)
        for value in numeric_values
    ):
        raise TypeError(
            "sales_lower, sales_upper, profit_margin_min, and "
            "profit_margin_max must be numeric"
        )

    if sales_lower > sales_upper:
        raise ValueError("sales_lower cannot be greater than sales_upper")
    if profit_margin_min > profit_margin_max:
        raise ValueError(
            "profit_margin_min cannot be greater than profit_margin_max"
        )

    rng = np.random.default_rng(random_seed)
    rows = []

    for product in products:
        sales = rng.uniform(sales_lower, sales_upper, size=n_samples)
        margins = rng.uniform(
            profit_margin_min, profit_margin_max, size=n_samples
        )
        profits = sales * margins

        rows.extend(
            {
                "Product": product,
                "Sales": sale,
                "Profit": profit,
            }
            for sale, profit in zip(sales, profits)
        )

    if not rows:
        return pd.DataFrame(columns=["Product", "Sales", "Profit"])

    return (
        pd.DataFrame(rows)
        .groupby("Product", as_index=False)[["Sales", "Profit"]]
        .sum()
        .sort_values("Profit", ascending=False)
        .reset_index(drop=True)
    )

