from itertools import combinations
import math


def task_func(seq, letter_weight_dict):
    """Return a maximum-weight subsequence of seq."""
    best_subsequence = ""
    best_weight = 0

    for size in range(1, len(seq) + 1):
        for subsequence in combinations(seq, size):
            weight = sum(letter_weight_dict.get(character, 0) for character in subsequence)
            if weight > best_weight:
                best_weight = weight
                best_subsequence = "".join(subsequence)

    return best_subsequence

