import random


def task_func(list_length: int, k: int):
    if list_length < 0:
        raise ValueError("list_length must be non-negative")
    if k < 0 or k > list_length:
        raise ValueError("k must be between 0 and list_length")

    numbers = [random.randint(1, 100) for _ in range(list_length)]
    min_heap = []

    for number in numbers:
        if len(min_heap) < k:
            heapq.heappush(min_heap, number)
        elif number > min_heap[0]:
