import numpy as np
from scipy.optimize import curve_fit


def task_func(x, y, labels):
    import matplotlib.pyplot as plt

    try:
        dataset_count = len(x)
        if len(y) != dataset_count or len(labels) != dataset_count:
            raise ValueError("x, y, and labels must contain the same number of datasets")
    except TypeError as exc:
        raise ValueError("x, y, and labels must be sized collections") from exc

    def exponential_func(values, a, b, c):
        return a * np.exp(-b * values) + c

    fig, ax = plt.subplots()

    for x_data, y_data, label in zip(x, y, labels):
        x_values = np.asarray(x_data, dtype=float)
        y_values = np.asarray(y_data, dtype=float)

        if x_values.ndim != 1 or y_values.ndim != 1:
            raise ValueError("Each dataset must be one-dimensional")
        if x_values.size != y_values.size:
            raise ValueError("Each x and y dataset must have matching lengths")
        if x_values.size < 3:
            raise ValueError("Each dataset must contain at least three points")
        if not np.all(np.isfinite(x_values)) or not np.all(np.isfinite(y_values)):
            raise ValueError("Dataset values must be finite")
        if np.ptp(x_values) == 0:
            raise ValueError("Each x dataset must contain at least two distinct values")

        x_span = np.ptp(x_values)
        initial_guess = [
            float(np.ptp(y_values)),
            1.0 / x_span,
            float(np.min(y_values)),
        ]

        try:
            parameters, _ = curve_fit(
                exponential_func,
                x_values,
                y_values,
                p0=initial_guess,
                maxfev=10000,
            )
        except (RuntimeError, ValueError) as exc:
            raise ValueError(f"Could not fit dataset {label!r}") from exc

        curve_x = np.linspace(np.min(x_values), np.max(x_values), 300)
        curve_y = exponential_func(curve_x, *parameters)
        ax.plot(curve_x, curve_y, label=label)

    ax.set_xlabel("x")
    ax.set_ylabel("y")
    ax.set_title("Exponential Curve Fits")
    if dataset_count:
        ax.legend()
    ax.grid(True)
    fig.tight_layout()

    return fig

