import re
import pandas as pd
from datetime import datetime

def task_func(log_file):
    records = []
    pattern = re.compile(
        r"^(?P<type>[^:\[\]]+):\s*\[(?P<timestamp>[^\]]*)\]\s*-\s*(?P<message>.*)$"
    )

    with open(log_file, "r", encoding="utf-8") as file:
        for line in file:
            line = line.strip()
            if not line:
                continue

            match = pattern.match(line)
            if not match:
                continue

            log_type = match.group("type").strip()
            timestamp = match.group("timestamp")
            parsed_timestamp = datetime.strptime(timestamp, "%Y-%m-%d %H:%M:%S")

            if parsed_timestamp.strftime("%Y-%m-%d %H:%M:%S") != timestamp:
                raise ValueError(f"Invalid timestamp: {timestamp}")

            if not log_type:
                continue

            records.append(
                {
                    "type": log_type,
                    "timestamp": timestamp,
                    "message": match.group("message"),
                }
            )

    if not records:
        raise ValueError("No valid log entries found")

    output_file = re.sub(r"\.[^./\\]+$", "", str(log_file)) + ".csv"
    pd.DataFrame(records, columns=["type", "timestamp", "message"]).to_csv(
        output_file, index=False
    )

    return str(output_file)

