# Constants
HEADERS = {
    'accept': 'application/json'
}


def task_func(url, parameters):
    if not isinstance(url, str) or not url.strip():
        raise Exception("Invalid URL")

    if not isinstance(parameters, dict):
        raise Exception("Invalid parameters")

    try:
        response = requests.get(
            url,
            params=parameters,
            headers=HEADERS,
            timeout=30
        )

        if not 200 <= response.status_code < 300:
            raise Exception("URL cannot be accessed")

        response.raise_for_status()
        data = response.json()
    except Exception as exc:
        raise Exception("Unable to access or parse the URL") from exc

    if data is None or data == "" or data == [] or data == {}:
        raise Exception("Empty data")

    if isinstance(data, dict):
        for key in ("data", "results", "items", "records"):
            if key in data:
                data = data[key]
                break
        else:
            data = [data]

    if not isinstance(data, list) or not data:
        raise Exception("Invalid data")

    if not all(isinstance(record, dict) for record in data):
        raise Exception("Invalid data")

    try:
        dataframe = pd.DataFrame(data)
    except Exception as exc:
        raise Exception("Invalid data") from exc

    if dataframe.empty:
        raise Exception("Empty data")

    numerical = dataframe.select_dtypes(include="number")
    if numerical.empty:
        raise Exception("No numerical characteristics")

    correlation = numerical.corr()
    if correlation.empty:
        raise Exception("Unable to calculate correlations")

    _, axes = plt.subplots()
    sns.heatmap(
        correlation,
        ax=axes,
        annot=True,
        cmap="coolwarm",
        vmin=-1,
        vmax=1,
        center=0
    )
    axes.set_title("Correlation Heatmap")
    plt.show()

    return dataframe, axes

import random
import re


def task_func(text, seed=None):
    rng = random.Random(seed)

    def scramble(match):
        word = match.group(0)
        if len(word) <= 3:
            return word

        middle = list(word[1:-1])
        rng.shuffle(middle)
        return word[0] + "".join(middle) + word[-1]

    return re.sub(r"\b\w+\b", scramble, text)

import subprocess
import os
import time
import glob


def task_func(r_script_path: str, output_path: str, duration: int) -> (bool, str):
    success_message = "File generated successfully within the specified duration."
    failure_message = "File not generated within the specified duration."

    if duration < 0 or not os.path.isfile(r_script_path):
        return False, failure_message

    start_time = time.monotonic()
    deadline = start_time + duration

    try:
        process = subprocess.Popen(["Rscript", r_script_path])
    except (OSError, subprocess.SubprocessError):
        return False, failure_message

    try:
        while True:
            if any(os.path.isfile(path) for path in glob.glob(output_path)):
                return True, success_message

            remaining = deadline - time.monotonic()
            if remaining <= 0:
                return False, failure_message

            time.sleep(min(0.1, remaining))
    finally:
        if process.poll() is None:
            process.terminate()
            try:
                process.wait(timeout=1)
            except subprocess.TimeoutExpired:
                process.kill()
                process.wait()

