import pandas as pd


def task_func(
    start_time,
    end_time,
    step,
    columns=["Timestamp", "Sensor1", "Sensor2", "Sensor3", "SensorStatus"],
    sensor_statuses=["OK", "MAINTENANCE_REQUIRED", "ERROR"],
    random_seed=42,
):
    if len(columns) != 5:
        raise ValueError("columns must contain exactly five names")
    if not sensor_statuses:
        raise ValueError("sensor_statuses must not be empty")

    try:
        start = pd.to_datetime(start_time)
        end = pd.to_datetime(end_time)
    except Exception as exc:
        raise ValueError("start_time and end_time must be datetime-compatible") from exc

    if pd.isna(start) or pd.isna(end):
        raise ValueError("start_time and end_time must be valid datetimes")

    try:
        frequency = pd.Timedelta(step)
    except Exception as exc:
        raise ValueError("step must be a valid timedelta") from exc

    if frequency <= pd.Timedelta(0):
        raise ValueError("step must be positive")
    if start > end:
        raise ValueError("start_time must not be later than end_time")

    timestamps = pd.date_range(start=start, end=end, freq=frequency)
    rng = np.random.default_rng(random_seed)

    seconds = np.asarray([timestamp.timestamp() for timestamp in timestamps], dtype=float)
    noise = rng.normal(0.0, 0.01, size=(len(timestamps), 3))

    sensor1 = np.sin(seconds) + noise[:, 0]
    sensor2 = np.cos(seconds) + noise[:, 1]
    sensor3 = np.tan(seconds) + noise[:, 2]
    sensor3 = np.where(np.isfinite(sensor3), sensor3, np.nan)

    statuses = rng.choice(sensor_statuses, size=len(timestamps))

    return pd.DataFrame(
        {
            columns[0]: timestamps,
            columns[1]: sensor1,
            columns[2]: sensor2,
            columns[3]: sensor3,
            columns[4]: statuses,
        }
    )

