import pandas as pd
import os


def task_func(f_list, file_path):
    if (
        not isinstance(f_list, list)
        or not f_list
        or any(not inspect.isfunction(func) for func in f_list)
    ):
        raise ValueError("f_list must be a non-empty list of functions")

    try:
        file_path = os.fspath(file_path)
        if not file_path or not file_path.strip():
            raise ValueError("file_path must be a valid path")
    except (TypeError, ValueError):
        raise ValueError("file_path must be a valid path")

    rows = []

    for func in f_list:
        signature = inspect.signature(func)

        defaults = {
            name: parameter.default
            for name, parameter in signature.parameters.items()
            if parameter.default is not inspect.Parameter.empty
        }

        annotations = {
            name: parameter.annotation
            for name, parameter in signature.parameters.items()
            if parameter.annotation is not inspect.Parameter.empty
        }

        if signature.return_annotation is not inspect.Signature.empty:
            annotations["return"] = signature.return_annotation

        rows.append(
            {
                "Function Name": func.__name__,
                "Number of Arguments": len(signature.parameters),
                "Defaults": str(defaults),
                "Annotations": str(annotations),
                "Is Lambda": func.__name__ == "<lambda>",
            }
        )

    dataframe = pd.DataFrame(
        rows,
        columns=[
            "Function Name",
            "Number of Arguments",
            "Defaults",
            "Annotations",
            "Is Lambda",
        ],
    )

    try:
        dataframe.to_csv(file_path, index=False)
    except Exception as exc:
        raise IOError(f"Could not write CSV file: {file_path}") from exc

    return None

import numpy as np
import matplotlib.pyplot as plt
from scipy import stats
from sklearn.preprocessing import StandardScaler


def task_func(data, column, outlier_z_score):
    try:
        threshold = float(outlier_z_score)
    except (TypeError, ValueError) as exc:
        raise ValueError("outlier_z_score must be a finite numeric value.") from exc

    if not np.isfinite(threshold):
        raise ValueError("outlier_z_score must be a finite numeric value.")
    if threshold < 0:
        raise ValueError("outlier_z_score must be non-negative.")

    if isinstance(data, np.ndarray) and data.ndim >= 2:
        try:
            values = np.asarray(data[:, column])
        except (IndexError, TypeError) as exc:
            raise KeyError(f"Column {column!r} was not found.") from exc
    else:
        try:
            values = np.asarray(data[column])
        except (KeyError, IndexError, TypeError) as exc:
            raise KeyError(f"Column {column!r} was not found.") from exc

    if values.ndim != 1:
        values = values.reshape(-1)

    try:
        numeric_values = values.astype(float)
    except (TypeError, ValueError) as exc:
        raise ValueError("The selected column must contain numeric values.") from exc

    if not np.all(np.isfinite(numeric_values)):
        raise ValueError("The selected column must contain only finite values.")

    original_data = data.copy()
    n_rows = numeric_values.size

    if n_rows <= 1 or np.all(numeric_values == numeric_values[0]):
        outlier_mask = np.zeros(n_rows, dtype=bool)
    else:
        standardized = StandardScaler().fit_transform(
            numeric_values.reshape(-1, 1)
        ).ravel()
        z_scores = np.asarray(stats.zscore(standardized)).ravel()
        outlier_mask = np.abs(z_scores) > threshold

    if hasattr(data, "loc"):
        data_without_outliers = data.loc[~outlier_mask].copy()
        outlier_indices = data.index[outlier_mask]
    else:
        data_without_outliers = data[~outlier_mask].copy()
        outlier_indices = np.flatnonzero(outlier_mask)

    x_original = np.arange(n_rows)
    x_filtered = np.flatnonzero(~outlier_mask)

    plt.figure()
    plt.scatter(x_original, numeric_values)
    plt.title("Data with Outliers")
    plt.xlabel("Row")
    plt.ylabel(str(column))
    plt.tight_layout()

    plt.figure()
    plt.scatter(x_filtered, numeric_values[~outlier_mask])
    plt.title("Data without Outliers")
    plt.xlabel("Row")
    plt.ylabel(str(column))
    plt.tight_layout()

    plt.show()

    return original_data, data_without_outliers, outlier_indices

