        raise TypeError("rows must be a non-negative integer")
    if isinstance(columns, bool) or not isinstance(columns, (int, np.integer)):
        raise TypeError("columns must be a non-negative integer")
    if rows < 0 or columns < 0:
        raise ValueError("rows and columns must be non-negative")

    def generate_value(data_type):
        if data_type is str:
            return "".join(choice("abcdefghijklmnopqrstuvwxyz") for _ in range(5))
        if data_type is int:
            return int(np.random.randint(0, 10))
        if data_type is float:
            return float(np.random.randint(0, 10))
        if data_type is list:
            length = int(np.random.randint(1, 6))
            return [int(value) for value in np.random.randint(0, 10, length)]
        if data_type is tuple:
            length = int(np.random.randint(1, 6))
            return tuple(int(value) for value in np.random.randint(0, 10, length))
        if data_type is dict:
            length = int(np.random.randint(1, 6))
            keys = np.random.choice(10, length, replace=False)
            values = np.random.randint(0, 10, length)
            return {int(key): int(value) for key, value in zip(keys, values)}
        if data_type is set:
            length = int(np.random.randint(1, 6))
            return {
                int(value)
                for value in np.random.choice(10, length, replace=False)
            }
        raise ValueError("Unsupported data type")

    return pd.DataFrame(
        {
            f"col{column_index}": [
                generate_value(choice(DATA_TYPES)) for _ in range(rows)
            ]
            for column_index in range(columns)
        }
    )

