# Constants
LETTERS = list(string.ascii_lowercase)


def task_func(rows=1000, string_length=3):
    """Generate random strings and plot letter-frequency correlations."""
    if not isinstance(rows, int) or isinstance(rows, bool):
        raise TypeError("rows must be an integer")
    if not isinstance(string_length, int) or isinstance(string_length, bool):
        raise TypeError("string_length must be an integer")
    if rows < 0:
        raise ValueError("rows must be non-negative")
    if string_length < 0:
        raise ValueError("string_length must be non-negative")

    data = pd.DataFrame(
        {
            "string": [
                "".join(random.choices(LETTERS, k=string_length))
                for _ in range(rows)
            ]
        }
    )

    if data.empty:
        print("No data to generate heatmap.")
        return None

    exploded = data["string"].apply(list).explode()
    one_hot = pd.get_dummies(exploded, dtype=int).reindex(
        columns=LETTERS, fill_value=0
    )
    frequencies = (
        one_hot.groupby(level=0).sum()
        .reindex(range(rows), fill_value=0)
        .reindex(columns=LETTERS, fill_value=0)
    )

    correlation_matrix = frequencies.corr()
    ax = sns.heatmap(correlation_matrix, cmap="coolwarm", center=0)
    ax.set_title("Correlation of Letter Frequencies")
    ax.set_xlabel("Letters")
    ax.set_ylabel("Letters")

