import os
import requests
from zipfile import ZipFile, BadZipFile


def task_func(url, download_path="mnt/data/downloads/"):
    temp_path = None

    try:
        os.makedirs(download_path, exist_ok=True)

        response = requests.get(url, stream=True)
        response.raise_for_status()

        content_type = response.headers.get("Content-Type")
        if content_type != "application/zip":
            return "Error: The URL does not point to a ZIP file."

        temp_path = os.path.join(download_path, "downloaded_file.zip")

        with open(temp_path, "wb") as zip_file:
            for chunk in response.iter_content(chunk_size=8192):
                if chunk:
                    zip_file.write(chunk)

        try:
            with ZipFile(temp_path, "r") as archive:
                if archive.testzip() is not None:
                    raise BadZipFile("Corrupt ZIP file")
                archive.extractall(download_path)
        except Exception:
            return "Error: The downloaded file is not a valid ZIP file."

        return os.path.abspath(download_path)

    except requests.RequestException:
        return "Error: Unable to download the file from the provided URL."
    except Exception as exc:
        return f"Error: {exc}"
    finally:
        if temp_path and os.path.exists(temp_path):
            try:
                os.remove(temp_path)
            except Exception:
                pass

