import os
import shutil


def task_func(path, delimiter="/"):
    if not isinstance(path, str) or not path.strip():
        raise ValueError("path must be a non-empty string")

    if not isinstance(delimiter, str) or not delimiter:
        raise ValueError("delimiter must be a non-empty string")

    drive, remainder = os.path.splitdrive(path)

    if drive and not os.path.isabs(path):
        raise ValueError("drive-relative paths are invalid")

    source = remainder if drive else path
    parts = source.split(delimiter)
    absolute = os.path.isabs(path)

    if absolute:
        if not parts or parts[0] != "":
            raise ValueError("invalid absolute path")
        parts = parts[1:]

    if not parts:
        return []

    if any(part in ("", ".", "..") for part in parts):
        raise ValueError("path contains invalid components")

    separators = {os.sep}
    if os.altsep:
        separators.add(os.altsep)

    for part in parts:
        if "\x00" in part or any(
            separator in part and separator != delimiter
            for separator in separators
        ):
            raise ValueError("path contains invalid components")

    current = drive + os.sep if absolute and drive else os.sep if absolute else ""
    result = []

    for component in parts:
        current = os.path.join(current, component)

        if not os.path.exists(current):
            raise FileNotFoundError(current)

        if not os.path.isdir(current):
            raise ValueError(f"not a directory: {current}")

        usage = shutil.disk_usage(current)
        result.append(
            (
                component,
                {
                    "total": usage.total,
                    "used": usage.used,
                    "free": usage.free,
                },
            )
        )

    return result

