from collections.abc import Mapping, Sequence
import math

# Constants
TEAMS = ['Team A', 'Team B', 'Team C', 'Team D', 'Team E']
GOALS_RANGE = (-10, 10)


def task_func(goals, penalties):
    def normalize(values, name):
        if isinstance(values, Mapping):
            if set(values) != set(TEAMS):
                raise ValueError(
                    f"{name} must contain exactly the teams: {', '.join(TEAMS)}"
                )
            raw_values = [values[team] for team in TEAMS]
        elif isinstance(values, Sequence) and not isinstance(
            values, (str, bytes, bytearray)
        ):
            if len(values) != len(TEAMS):
                raise ValueError(f"{name} must contain exactly five values")
            raw_values = list(values)
        else:
            raise ValueError(
                f"{name} must be a mapping or a five-element sequence"
            )

        normalized = []
        for value in raw_values:
            if isinstance(value, bool):
                raise ValueError(f"{name} values must be numeric")
            try:
                number = float(value)
            except (TypeError, ValueError):
                raise ValueError(f"{name} values must be numeric") from None
            if not math.isfinite(number):
                raise ValueError(f"{name} values must be finite")
            normalized.append(number)
        return normalized

    goal_values = normalize(goals, "goals")
    penalty_values = normalize(penalties, "penalties")

    scores = [
        max(GOALS_RANGE[0], min(GOALS_RANGE[1], goal - penalty))
        for goal, penalty in zip(goal_values, penalty_values)
    ]

    result = pd.DataFrame({"Team": TEAMS, "Score": scores})

    plt.bar(result["Team"], result["Score"])
    plt.xlabel("Team")
    plt.ylabel("Score")
    plt.ylim(*GOALS_RANGE)

    return result

