from datetime import datetime
import pandas as pd
import numpy as np


def task_func(start_time, end_time, step, amplitude, period, seed=0):
    """Generate and plot a sinusoidal time series with seasonality."""
    import matplotlib.pyplot as plt

    start = pd.Timestamp(start_time)
    end = pd.Timestamp(end_time)

    if pd.isna(start) or pd.isna(end):
        raise ValueError("start_time and end_time must be valid datetimes")

    start = start.tz_localize("UTC") if start.tzinfo is None else start.tz_convert("UTC")
    end = end.tz_localize("UTC") if end.tzinfo is None else end.tz_convert("UTC")

    if end < start:
        raise ValueError("end_time must not precede start_time")

    try:
        amplitude = float(amplitude)
    except (TypeError, ValueError) as exc:
        raise ValueError("amplitude must be numeric") from exc

    if not np.isfinite(amplitude):
        raise ValueError("amplitude must be finite")

    if isinstance(period, bool) or not isinstance(period, (int, np.integer)):
        raise ValueError("period must be a positive integer")
    if period <= 0:
        raise ValueError("period must be a positive integer")

    try:
        offset = pd.tseries.frequencies.to_offset(step)
        if offset.nanos <= 0:
            raise ValueError
        timestamps = pd.date_range(start=start, end=end, freq=offset)
    except (TypeError, ValueError, OverflowError) as exc:
        raise ValueError("step must be a valid positive time frequency") from exc

    if len(timestamps) == 0:
        raise ValueError("The requested time range contains no timestamps")

    index = np.arange(len(timestamps), dtype=float)
    values = amplitude * np.sin(2 * np.pi * index / period)

    _, ax = plt.subplots()
    ax.plot(timestamps, values)
    ax.set_xlabel("Timestamp")
    ax.set_ylabel("Value")
    ax.set_title("Time Series with Seasonality")
    ax.figure.autofmt_xdate()

    return ax

