import re
import nltk
import pandas as pd
from sklearn.feature_extraction.text import CountVectorizer
# Make sure to download NLTK stopwords
nltk.download('stopwords')
# Define a regex pattern for matching all non-alphanumeric characters
ALPHANUMERIC = re.compile('[\W_]+')
# Load NLTK's list of English stop words
STOPWORDS = nltk.corpus.stopwords.words('english')


def task_func(texts):
    """Create a document-term matrix from a list of text documents."""
    texts = list(texts)

    processed_texts = []
    for text in texts:
        if not isinstance(text, str):
            raise TypeError("Each document must be a string.")
        processed_texts.append(ALPHANUMERIC.sub(" ", text).lower())

    if not processed_texts:
        return pd.DataFrame()

    vectorizer = CountVectorizer(stop_words=STOPWORDS)

    try:
        matrix = vectorizer.fit_transform(processed_texts)
    except ValueError as error:
        if "empty vocabulary" not in str(error).lower():
            raise
        return pd.DataFrame(index=range(len(processed_texts)))

    return pd.DataFrame(
        matrix.toarray(),
        index=range(len(processed_texts)),
        columns=vectorizer.get_feature_names_out(),
    )

