import subprocess
import psutil
import time
import os


def task_func(script_path: str, timeout=10) -> dict:
    if not os.path.isfile(script_path):
        raise FileNotFoundError(f"Script not found: {script_path}")

    process = subprocess.Popen(["bash", script_path])
    monitored_process = psutil.Process(process.pid)

    cpu_usage = 0.0
    memory_usage = 0
    start_time = time.monotonic()
    timed_out = False

    try:
        monitored_process.cpu_percent(None)

        while process.poll() is None:
            remaining = timeout - (time.monotonic() - start_time)
            if remaining <= 0:
                timed_out = True
                break

            interval = min(0.1, remaining)

            try:
                cpu_usage += monitored_process.cpu_percent(interval=interval)
                memory_usage += monitored_process.memory_info().rss

                if monitored_process.status() == psutil.STATUS_ZOMBIE:
                    break
            except (psutil.NoSuchProcess, psutil.ZombieProcess):
                break
    finally:
        if timed_out and process.poll() is None:
            try:
                process.terminate()
                process.wait(timeout=0.5)
            except subprocess.TimeoutExpired:
                process.kill()
                process.wait()
            except ProcessLookupError:
                pass
        elif process.poll() is None:
            process.wait()

    return {
        "CPU Usage": cpu_usage,
        "Memory Usage": memory_usage,
    }

