import zipfile

def task_func(directory):
    if not os.path.exists(directory):
        raise FileNotFoundError(directory)
    if not os.path.isdir(directory):
        raise NotADirectoryError(directory)

    pattern = os.path.join(glob.escape(os.fspath(directory)), "*")
    files = [
        path
        for path in glob.glob(pattern)
        if os.path.isfile(path) and os.path.basename(path) != "files.zip"
    ]

    if not files:
        return None

    zip_path = os.path.join(os.fspath(directory), "files.zip")

    with zipfile.ZipFile(zip_path, "w", zipfile.ZIP_DEFLATED) as archive:
        for file_path in files:
            archive.write(file_path, arcname=os.path.basename(file_path))

    return zip_path

import json
import re
from collections import Counter

# Constants
REPLACE_NONE = "None"


def task_func(json_str):
    data = json.loads(json_str)
    value_counts = Counter()
    email_pattern = re.compile(
        r"(?<![\w.+-])[\w.+-]+@[\w-]+(?:\.[\w-]+)+(?![\w.-])"
    )

    def process(value):
        if value is None:
            return None

        if isinstance(value, dict):
            return {
                key: process(item)
                for key, item in value.items()
                if item is not None
            }

        if isinstance(value, list):
            return [
                process(item)
                for item in value
                if item is not None
            ]

        if isinstance(value, str):
            return email_pattern.sub(REPLACE_NONE, value)

        return value

    def count_values(value):
        if isinstance(value, dict):
            for item in value.values():
                count_values(item)
        elif isinstance(value, list):
            for item in value:
                count_values(item)
        elif value is not None:
            value_counts[value] += 1

    processed_data = process(data)
    count_values(processed_data)

    return {
        "data": processed_data,
        "value_counts": value_counts,
    }

