import math

def task_func(x, w):
    if not x:
        return ""

    current_sum = best_sum = w[x[0]]
    current_start = best_start = 0
    best_end = 0

    for end in range(1, len(x)):
        weight = w[x[end]]

        if current_sum + weight < weight:
            current_sum = weight
            current_start = end
        else:
            current_sum += weight

        if current_sum > best_sum:
            best_sum = current_sum
            best_start = current_start
            best_end = end

    return x[best_start:best_end + 1]

