        Mapping from acronyms to their full words.

    Returns
    -------
    pd.DataFrame
        A copy of the DataFrame with acronyms replaced in string cells.
    """
    if not isinstance(data, pd.DataFrame):
        raise TypeError("data must be a pandas DataFrame")

    if not hasattr(mapping, "items"):
        raise TypeError("mapping must be a dictionary-like object")

    replacements = {
        str(key): str(value)
        for key, value in mapping.items()
        if str(key)
    }

    result = data.copy()

    if not replacements:
        return result

    keys = sorted(replacements, key=len, reverse=True)
    pattern = re.compile(
        r"(?<!\w)(?:" + "|".join(re.escape(key) for key in keys) + r")(?!\w)"
    )

    def replace_acronyms(value):
        if not isinstance(value, str):
            return value
        return pattern.sub(lambda match: replacements[match.group(0)], value)

    for column in result.columns:
        result[column] = result[column].map(replace_acronyms)

    return result

