from statsmodels.tsa.seasonal import seasonal_decompose


def task_func(df, freq='D', decomposition_model='multiplicative'):
    if not isinstance(df, pd.DataFrame):
        raise ValueError("'df' must be a pandas DataFrame.")

    if 'value' not in df.columns:
        raise ValueError("DataFrame must contain a 'value' column.")

    if decomposition_model not in ('additive', 'multiplicative'):
        raise ValueError(
            "decomposition_model must be 'additive' or 'multiplicative'."
        )

    if not isinstance(freq, str) or not freq.strip():
        raise ValueError("'freq' must be a valid frequency string.")

    try:
        offset = pd.tseries.frequencies.to_offset(freq)
    except (TypeError, ValueError):
        raise ValueError("'freq' must be a valid frequency string.")

    if getattr(offset, 'n', 1) <= 0:
        raise ValueError("'freq' must be a valid frequency string.")

    values = df['value']

    if isinstance(values, pd.DataFrame):
        raise ValueError("'value' must be a single column.")

    if (
        not pd.api.types.is_numeric_dtype(values)
        or pd.api.types.is_bool_dtype(values)
        or pd.api.types.is_complex_dtype(values)
    ):
        raise ValueError("'value' must contain numeric data.")

    try:
        values = values.astype(float)
    except (TypeError, ValueError):
        raise ValueError("'value' contains invalid data.")

    if values.isna().any() or not values.map(pd.isna).eq(False).all():
        raise ValueError("'value' contains invalid data.")

    if values.map(lambda value: value in (float('inf'), float('-inf'))).any():
        raise ValueError("'value' contains invalid data.")

    if decomposition_model == 'multiplicative' and (values <= 0).any():
        raise ValueError(
            "Multiplicative decomposition requires positive values."
        )

    name = str(getattr(offset, 'name', '')).upper()
    count = int(getattr(offset, 'n', 1))

    if name.startswith(('BH', 'H', 'HR')):
        period = max(2, round(24 / count))
    elif name.startswith(('T', 'MIN')):
        period = max(2, round(60 / count))
    elif name.startswith('S'):
        period = max(2, round(60 / count))
    elif name.startswith(('D', 'B', 'C')):
        period = max(2, round(7 / count))
    elif name.startswith('W'):
        period = max(2, round(52 / count))
    elif name.startswith(('M', 'ME', 'MS')):
        period = max(2, round(12 / count))
    elif name.startswith(('Q', 'QE', 'QS')):
        period = max(2, round(4 / count))
    else:
        raise ValueError("The supplied frequency is not supported.")

    if len(values) < 2 * period:
        raise ValueError(
            "At least two complete seasonal cycles are required."
        )

    try:
        result = seasonal_decompose(
            values,
            model=decomposition_model,
            period=period,
        )
        figure = result.plot()
    except (TypeError, ValueError, IndexError) as exc:
        raise ValueError(f"Unable to decompose the time series: {exc}") from exc

    return result, figure.axes[0]

