import os
import re
from pathlib import Path


def task_func(dir_path: str, predicates: list) -> dict:
    directory = Path(dir_path)

    if not directory.exists() or not directory.is_dir():
        raise FileNotFoundError(f"Directory does not exist: {dir_path}")

    valid_predicates = []
    seen = set()

    try:
        predicate_iter = iter(predicates)
    except TypeError as exc:
        raise ValueError("No valid predicates were provided") from exc

    for predicate in predicate_iter:
        if not isinstance(predicate, str) or predicate in seen:
            continue

        try:
            compiled = re.compile(predicate)
        except re.error:
            continue

        seen.add(predicate)
        valid_predicates.append(compiled)

    if not valid_predicates:
        raise ValueError("No valid predicates were provided")

    return {
        item_name: [
            predicate.search(item_name) is not None
            for predicate in valid_predicates
        ]
        for item_name in os.listdir(directory)
    }

import os
import shutil


def task_func(src_dir, dest_dir, extension):
    if not os.path.isdir(src_dir):
        raise FileNotFoundError(f"Source directory does not exist: {src_dir}")

    src_path = os.path.realpath(src_dir)
    dest_path = os.path.realpath(dest_dir)

    if src_path == dest_path:
        return {"files_moved": 0}

    os.makedirs(dest_dir, exist_ok=True)

    files_moved = 0
    for name in os.listdir(src_dir):
        source_path = os.path.join(src_dir, name)

        if os.path.isfile(source_path) and name.endswith(extension):
            shutil.move(source_path, os.path.join(dest_dir, name))
            files_moved += 1

    return {"files_moved": files_moved}

