# Constants
COLUMNS = ['A', 'B', 'C', 'D', 'E']


def task_func(df, tuples, n_plots):
    if not isinstance(df, pd.DataFrame):
        raise TypeError("df must be a pandas DataFrame")

    if isinstance(n_plots, bool) or not isinstance(n_plots, int):
        raise TypeError("n_plots must be a non-negative integer")
    if n_plots < 0:
        raise ValueError("n_plots must be non-negative")

    filtered_df = df.copy()
    conditions = list(tuples)

    if conditions:
        mask = pd.Series(True, index=filtered_df.index)

        for condition in conditions:
            if not isinstance(condition, (tuple, list)) or len(condition) != 2:
                raise ValueError(
                    "Each filtering condition must be a (column, value) pair"
                )

            column, value = condition

            if column not in COLUMNS:
                raise ValueError(f"Unsupported column: {column}")
            if column not in filtered_df.columns:
                raise ValueError(f"Column not found in DataFrame: {column}")

            mask &= filtered_df[column].eq(value)

        filtered_df = filtered_df.loc[~mask].copy()

    available_columns = [
        column for column in COLUMNS if column in filtered_df.columns
    ]
    available_pairs = list(combinations(available_columns, 2))
    selected_pairs = sample(
        available_pairs,
        min(n_plots, len(available_pairs)),
    )

    for x_column, y_column in selected_pairs:
        plt.plot(filtered_df[x_column], filtered_df[y_column])
        plt.xlabel(x_column)
        plt.ylabel(y_column)
        plt.show()

    return filtered_df, selected_pairs

