import random
from numbers import Integral, Real
import math


def task_func(data, columns=['Name', 'Age', 'Occupation'], fill_missing=False, num_range=(0, 100), seed=None):
    try:
        if len(num_range) != 2:
            raise ValueError
        lower, upper = num_range
    except (TypeError, ValueError):
        raise ValueError("num_range must contain exactly two values.")

    if (
        isinstance(lower, bool)
        or isinstance(upper, bool)
        or not isinstance(lower, Real)
        or not isinstance(upper, Real)
        or not math.isfinite(float(lower))
        or not math.isfinite(float(upper))
        or lower > upper
    ):
        raise ValueError("num_range must contain valid numeric bounds.")

    column_count = len(columns)
    rows = []

    for row in data:
        row = list(row)

        if len(row) > column_count:
            raise ValueError("A row contains more values than there are columns.")

        rows.append(row + [None] * (column_count - len(row)))

    df = pd.DataFrame(rows, columns=columns)

    if not fill_missing:
        return df

    rng = random.Random(seed)
    use_integers = isinstance(lower, Integral) and isinstance(upper, Integral)

    for column in df.columns:
        non_missing = df[column].dropna()

        if non_missing.empty:
            continue

        if not all(
            isinstance(value, Real) and not isinstance(value, bool)
            for value in non_missing
        ):
            continue

        def generate_value():
            if use_integers:
                return rng.randint(lower, upper)
            return rng.uniform(lower, upper)

        df[column] = df[column].map(
            lambda value: generate_value() if pd.isna(value) else value
        )

    return df

