import socket
import select
import queue
from datetime import datetime, timedelta


def task_func(
    server_address="localhost", server_port=12345, buffer_size=1024, run_duration=5
):
    start_time = datetime.now()
    deadline = start_time + timedelta(seconds=max(0, run_duration))

    try:
        server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        server_socket.setblocking(False)
        server_socket.bind((server_address, server_port))
        server_socket.listen()
    except OSError as exc:
        try:
            server_socket.close()
        except (NameError, OSError):
            pass
        return f"Server failed to start: {exc}"

    clients = set()
    outgoing = {}
    pending = {}

    def close_socket(sock):
        clients.discard(sock)
        outgoing.pop(sock, None)
        pending.pop(sock, None)
        try:
            sock.close()
        except OSError:
            pass

    try:
        while datetime.now() < deadline:
            timeout = max(0.0, (deadline - datetime.now()).total_seconds())
            readable_sockets = [server_socket, *clients]
            writable_sockets = [
                client
                for client in clients
                if client in pending or not outgoing[client].empty()
            ]
            exceptional_sockets = [server_socket, *clients]

            try:
                readable, writable, exceptional = select.select(
                    readable_sockets,
                    writable_sockets,
                    exceptional_sockets,
                    timeout,
                )
            except (OSError, ValueError):
                break

            if server_socket in exceptional:
                break

            if server_socket in readable:
                while True:
                    client = None
                    try:
                        client, _ = server_socket.accept()
                        client.setblocking(False)
                        clients.add(client)
                        outgoing[client] = queue.Queue()
                    except BlockingIOError:
                        break
                    except OSError:
                        if client is not None:
                            close_socket(client)
                        break

            for client in exceptional:
                if client in clients:
                    close_socket(client)

            for client in readable:
                if client not in clients:
                    continue

                try:
                    data = client.recv(buffer_size)
                    if not data:
                        close_socket(client)
                        continue

                    timestamp = datetime.now().isoformat().encode()
                    outgoing[client].put(data + timestamp)
                except (BlockingIOError, ConnectionError, OSError, ValueError):
                    close_socket(client)

            for client in writable:
                if client not in clients:
                    continue

                try:
                    response = pending.get(client)
                    if response is None:
                        response = outgoing[client].get_nowait()

                    sent = client.send(response)
                    if sent < len(response):
                        pending[client] = response[sent:]
                    else:
                        pending.pop(client, None)
                except queue.Empty:
                    pass
                except (BlockingIOError, ConnectionError, OSError, ValueError):
                    close_socket(client)
    finally:
        for client in list(clients):
            close_socket(client)

        try:
            server_socket.close()
        except OSError:
            pass

    elapsed = (datetime.now() - start_time).total_seconds()
    return f"Server operated for {elapsed:.2f} seconds"

