    y = rng.random(N)

    if N < len(categories):
        selected_categories = rng.choice(categories, size=N, replace=False)
    else:
        selected_categories = np.array(categories, dtype=object)

        remaining = N - len(categories)
        if remaining > 0:
            selected_categories = np.concatenate(
                [
                    selected_categories,
                    rng.choice(categories, size=remaining, replace=True),
                ]
            )

        rng.shuffle(selected_categories)

