import codecs
import re
import datetime


def task_func(start_year=1980, end_year=2000, email_domain='example.com',
              latin_names=['Sopetón', 'Méndez', 'Gómez', 'Pérez', 'Muñoz'],
              other_names=['Smith', 'Johnson', 'Williams', 'Brown', 'Jones'],
              rng_seed=None):

    if isinstance(start_year, bool) or isinstance(end_year, bool):
        raise TypeError("start_year and end_year must be integers")
    if not isinstance(start_year, (int, np.integer)) or not isinstance(
        end_year, (int, np.integer)
    ):
        raise TypeError("start_year and end_year must be integers")

    start_year = int(start_year)
    end_year = int(end_year)

    if not 0 <= start_year <= end_year <= 9999:
        raise ValueError(
            "Years must satisfy 0 <= start_year <= end_year <= 9999"
        )

    if not isinstance(email_domain, str) or not email_domain.strip():
        raise ValueError("email_domain must be a non-empty string")

    latin_names = list(latin_names)
    other_names = list(other_names)

    if not latin_names or not other_names:
        raise ValueError("Name lists must not be empty")

    names = latin_names + other_names
    if not all(isinstance(name, str) for name in names):
        raise TypeError("All names must be strings")

    def fix_encoding(name):
        corrected = name
        for _ in range(2):
            if not re.search(r"(?:Ã.|Â.|â.|ð.|Ð.)", corrected):
                break
            try:
                decoded = codecs.decode(corrected.encode("latin1"), "utf-8")
            except (UnicodeEncodeError, UnicodeDecodeError):
                break
            if decoded == corrected:
                break
            corrected = decoded
        return corrected

    def days_in_month(year, month):
        if month == 2:
            leap_year = year % 400 == 0 or (
                year % 4 == 0 and year % 100 != 0
            )
            return 29 if leap_year else 28
        return 30 if month in (4, 6, 9, 11) else 31

    rng = np.random.default_rng(rng_seed)

    selected_names = [
        fix_encoding(names[index])
        for index in rng.integers(0, len(names), size=100)
    ]

    years = rng.integers(start_year, end_year + 1, size=100)
    dates = []

    for year_value in years:
        year = int(year_value)
        month = int(rng.integers(1, 13))
        day = int(rng.integers(1, days_in_month(year, month) + 1))

        if year == 0:
            dates.append(f"{year:04d}-{month:02d}-{day:02d} 00:00:00")
        else:
            dates.append(datetime.datetime(year, month, day))

    emails = [
        f"{name.lower()}{int(year)}@{email_domain}"
        for name, year in zip(selected_names, years)
    ]

    return pd.DataFrame({
        "ID": range(1, 101),
        "Name": selected_names,
        "Date of Birth": pd.Series(dates, dtype=object),
        "Email": emails,
    })

