import pandas as pd
import numpy as np
from statsmodels.tsa.seasonal import seasonal_decompose


def task_func(start_date='2016-01-01', periods=24, freq='M', model='additive'):
    if isinstance(periods, bool) or not isinstance(periods, (int, np.integer)) or periods <= 0:
        raise ValueError("periods must be a positive integer")

    if not isinstance(model, str):
        raise ValueError("model must be either 'additive' or 'multiplicative'")

    model = model.lower()
    if model not in {'additive', 'multiplicative'}:
        raise ValueError("model must be either 'additive' or 'multiplicative'")

    frequency = str(freq).upper()
    if frequency.startswith('M'):
        seasonal_period = 12
    elif frequency.startswith('Q'):
        seasonal_period = 4
    elif frequency.startswith('W'):
        seasonal_period = 52
    elif frequency.startswith('D'):
        seasonal_period = 7
    elif frequency.startswith('H'):
        seasonal_period = 24
    else:
        raise ValueError("unsupported frequency")

    if periods < 2 * seasonal_period:
        raise ValueError(
            f"periods must contain at least two seasonal cycles "
            f"({2 * seasonal_period} observations required)"
        )

    index = pd.date_range(start=start_date, periods=periods, freq=freq)
    time = np.arange(periods, dtype=float)

    trend = 100.0 + 2.0 * time
    seasonal_wave = np.sin(2.0 * np.pi * time / seasonal_period)
    residual_wave = 2.0 * np.cos(2.0 * np.pi * time / (seasonal_period * 2))

    if model == 'multiplicative':
        sales = trend * (1.0 + 0.15 * seasonal_wave) * (1.0 + residual_wave / 100.0)
    else:
        sales = trend + 10.0 * seasonal_wave + residual_wave

    sales_series = pd.Series(sales, index=index, name='sales')
    decomposition = seasonal_decompose(
        sales_series,
        model=model,
        period=seasonal_period,
    )

    return {
        'trend': decomposition.trend,
        'seasonal': decomposition.seasonal,
        'residual': decomposition.resid,
    }

