import csv
import collections


def task_func(csv_file, emp_prefix='EMP$$'):
    should_close = False

    if isinstance(csv_file, (str, bytes)) or hasattr(csv_file, '__fspath__'):
        file_obj = open(csv_file, newline='', encoding='utf-8')
        should_close = True
    else:
        file_obj = csv_file

    try:
        reader = csv.DictReader(file_obj)
        if not reader.fieldnames:
            return {}

        fields = {
            field.strip().lower(): field
            for field in reader.fieldnames
            if field is not None
        }

        employee_field = next(
            (
                fields[name]
                for name in ('employee', 'employee_id', 'emp_id')
                if name in fields
            ),
            reader.fieldnames[0],
        )

        counts = collections.Counter()

        for row in reader:
            employee = (row.get(employee_field) or '').strip()
            if employee and employee.startswith(emp_prefix):
                counts[employee] += 1

        return dict(counts)
    finally:
        if should_close:
            file_obj.close()

