from string import punctuation


def task_func(df):
    required_columns = {"Title", "Content"}

    if df.empty or not required_columns.issubset(df.columns):
        raise ValueError(
            "DataFrame must be non-empty and contain 'Title' and 'Content' columns"
        )

    frequencies = {}

    for _, row in df.iterrows():
        title = row["Title"]
        content = row["Content"]

        if not isinstance(title, str) or not re.search(
            r"like|what", title, flags=re.IGNORECASE
        ):
            continue

        if not isinstance(content, str):
            continue

        words = re.findall(r"[^\W_]+", content.lower(), flags=re.UNICODE)

        for word in words:
            frequencies[word] = frequencies.get(word, 0) + 1

    return frequencies

