import collections
from itertools import zip_longest
from random import choices


def task_func(l1, l2, K=10):
    if K < 0:
        raise ValueError("K must be non-negative")

    sentinel = object()
    combined = []

    for first, second in zip_longest(l1, l2, fillvalue=sentinel):
        if first is not sentinel:
            combined.append(first)
        if second is not sentinel:
            combined.append(second)

    if K > 0 and not combined:
        raise ValueError("Cannot sample from an empty combined list")

    return collections.Counter(choices(combined, k=K))

import pandas as pd
from sklearn.linear_model import LinearRegression

DATA = {
    "Area_String": ["1,000", "2,000", "3,000", "4,000", "5,000"],
    "Price": [100, 200, 300, 400, 500],
}


def task_func(area_string, data=DATA):
    if "Area_String" not in data or "Price" not in data:
        raise KeyError("Data must contain 'Area_String' and 'Price' columns.")

    areas = pd.to_numeric(
        pd.Series(data["Area_String"], dtype="string").str.replace(
            ",", "", regex=False
        ),
        errors="coerce",
    )
    prices = pd.to_numeric(pd.Series(data["Price"]), errors="coerce")

    if len(areas) == 0 or len(prices) == 0:
        raise ValueError("Training data must not be empty.")

    if (
        len(areas) != len(prices)
        or areas.isna().any()
        or prices.isna().any()
        or not areas.isin([float("inf"), float("-inf")]).sum() == 0
        or not prices.isin([float("inf"), float("-inf")]).sum() == 0
    ):
        raise ValueError("Training data contains invalid or mismatched values.")

    normalized_area = pd.to_numeric(
        str(area_string).replace(",", ""), errors="coerce"
    )
    if pd.isna(normalized_area) or normalized_area in (float("inf"), float("-inf")):
        raise ValueError("area_string must be numeric.")

    model = LinearRegression()
    model.fit(areas.to_numpy().reshape(-1, 1), prices.to_numpy())

    return float(model.predict([[normalized_area]])[0])

