import warnings
import os
import glob
import shutil
import time


def task_func(SOURCE_DIR, DEST_DIR, EXTENSIONS):
    transferred_files = []

    try:
        source_dir = os.fsdecode(os.fspath(SOURCE_DIR))
        dest_dir = os.fsdecode(os.fspath(DEST_DIR))
    except (TypeError, ValueError) as exc:
        warnings.warn(f"Invalid directory path: {exc}")
        return transferred_files

    if not os.path.isdir(source_dir):
        warnings.warn(f"Source directory does not exist: {source_dir}")
        return transferred_files

    try:
        if os.path.realpath(source_dir) == os.path.realpath(dest_dir):
            warnings.warn("Source and destination directories must differ.")
            return transferred_files

        os.makedirs(dest_dir, exist_ok=True)
    except OSError as exc:
        warnings.warn(f"Could not prepare destination directory: {exc}")
        return transferred_files

    if isinstance(EXTENSIONS, str):
        extensions = [EXTENSIONS]
    else:
        try:
            extensions = list(EXTENSIONS)
        except (TypeError, ValueError) as exc:
            warnings.warn(f"EXTENSIONS must be a string or iterable: {exc}")
            return transferred_files

    normalized_extensions = set()
    for extension in extensions:
        if not isinstance(extension, str):
            warnings.warn(f"Ignoring invalid extension: {extension!r}")
            continue

        extension = extension.strip().lower()
        if extension:
            normalized_extensions.add(
                extension if extension.startswith(".") else f".{extension}"
            )

    try:
        source_entries = glob.glob(os.path.join(source_dir, "*"))
    except (OSError, TypeError) as exc:
        warnings.warn(f"Could not list source directory: {exc}")
        return transferred_files

    for source_path in source_entries:
        try:
            if os.path.islink(source_path) or not os.path.isfile(source_path):
                continue

            filename = os.path.basename(source_path)
            if os.path.splitext(filename)[1].lower() not in normalized_extensions:
                continue

            destination_path = os.path.join(dest_dir, filename)
            shutil.copy2(source_path, destination_path)
            transferred_files.append(filename)
        except (OSError, shutil.Error) as exc:
            warnings.warn(f"Could not transfer {source_path!r}: {exc}")

    return transferred_files

import pandas as pd
from random import seed, choices
from string import ascii_lowercase


def task_func(L, num_dataframes=5, random_seed=None):
    if random_seed is not None:
        seed(random_seed)

    if not L or num_dataframes <= 0:
        return pd.DataFrame(), []

    columns = choices(ascii_lowercase, k=3)

    df_list = [
        pd.DataFrame(choices(L, k=3), columns=columns)
        for _ in range(num_dataframes)
    ]

    if num_dataframes == 1:
        return df_list[0].copy(), df_list

    row_counts = []
    for dataframe in df_list:
        counts = {}
        for row in dataframe.itertuples(index=False, name=None):
            counts[row] = counts.get(row, 0) + 1
        row_counts.append(counts)

    common_counts = {
        row: min(counts.get(row, 0) for counts in row_counts)
        for row in row_counts[0]
    }

    common_data = []
    for row in df_list[0].itertuples(index=False, name=None):
        if common_counts.get(row, 0) > 0:
            common_data.append(row)
            common_counts[row] -= 1

    common_rows = pd.DataFrame(common_data, columns=columns)
    return common_rows, df_list

