import subprocess
import csv
import glob
import random
import os


def task_func(file):
    """Split a CSV file into smaller files and shuffle each file's rows."""
    generated_files = []

    try:
        if not isinstance(file, (str, bytes, os.PathLike)):
            return []

        source = os.path.abspath(os.fsdecode(os.fspath(file)))

        if not os.path.isfile(source) or not source.lower().endswith(".csv"):
            return []

        directory = os.path.dirname(source)
        token = f"{os.getpid()}_{abs(hash(source)):x}"
        prefix = os.path.join(directory, f"split_{token}_")

        subprocess.run(
            ["split", "-l", "1000", source, prefix],
            check=True,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
        )

        generated_files = sorted(
            path
            for path in glob.glob(prefix + "*")
            if os.path.isfile(path)
        )

        for path in generated_files:
            with open(path, "r", newline="", encoding="utf-8") as input_file:
                rows = list(csv.reader(input_file))

            random.shuffle(rows)

            with open(path, "w", newline="", encoding="utf-8") as output_file:
                csv.writer(output_file).writerows(rows)

        return generated_files

    except Exception:
        cleanup_pattern = (
            os.path.join(os.path.dirname(os.path.abspath(os.fsdecode(os.fspath(file)))),
                         "split_*")
            if isinstance(file, (str, bytes, os.PathLike))
            else None
        )

        paths = generated_files
        if cleanup_pattern:
            paths = set(paths) | set(glob.glob(cleanup_pattern))

        for path in paths:
            try:
                if os.path.isfile(path):
                    os.remove(path)
            except OSError:
                pass

        return []

import time
import numpy as np


def task_func(samples=10, delay=0.1):
    if isinstance(samples, bool) or not isinstance(samples, (int, np.integer)) or samples <= 0:
        raise ValueError("samples must be a positive integer")

    if (
        isinstance(delay, bool)
        or not isinstance(delay, (int, float, np.integer, np.floating))
        or not np.isfinite(delay)
        or delay < 0
    ):
        raise ValueError("delay must be a finite, non-negative number")

    delays = np.empty(int(samples), dtype=float)

    for index in range(int(samples)):
        start = time.perf_counter()
        time.sleep(delay)
        delays[index] = time.perf_counter() - start

    return float(np.mean(delays)), float(np.std(delays))

