        reordered_words = []

        for word, matches_pattern in zip(words, matches):
            if matches_pattern:
                reordered_words.append(matching_words[matching_index])
                matching_index += 1
            else:
                reordered_words.append(word)

        return " ".join(reordered_words)

    result = df.copy()
    result[column_name] = result[column_name].map(reverse_matching_words)
    return result

