import json
import os
import re


def task_func(
    file_path,
    attribute,
    INPUT_JSON={
        "type": "object",
        "properties": {
            "name": {"type": str},
            "age": {"type": int},
            "email": {"type": str}
        },
        "required": ["name", "age", "email"]
    },
    EMAIL_REGEX=r"^[a-z0-9]+[\._]?[a-z0-9]+[@]\w+[.]\w{2,3}$"
):
    if not isinstance(file_path, (str, os.PathLike)) or not os.path.isfile(file_path):
        raise ValueError("JSON file does not exist")

    try:
        with open(file_path, "r", encoding="utf-8") as file:
            data = json.load(file)
    except (OSError, UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise ValueError("Invalid JSON file") from exc

    if not isinstance(data, dict):
        raise ValueError("JSON root must be an object")

    if not isinstance(INPUT_JSON, dict):
        raise ValueError("Invalid schema")

    if INPUT_JSON.get("type", "object") != "object":
        raise ValueError("Schema root must be an object")

    properties = INPUT_JSON.get("properties", {})
    required = INPUT_JSON.get("required", [])

    if not isinstance(properties, dict) or not isinstance(required, list):
        raise ValueError("Invalid schema")

    for key in required:
        if not isinstance(key, str) or key not in properties:
            raise ValueError(f"Schema does not define required attribute: {key}")
        if key not in data:
            raise ValueError(f"Missing required attribute: {key}")

    for key, schema in properties.items():
        if key not in data:
            continue

        if not isinstance(schema, dict) or "type" not in schema:
            raise ValueError(f"Invalid schema for attribute: {key}")

        expected_type = schema["type"]
        value = data[key]

        try:
            valid_type = isinstance(value, expected_type)
        except TypeError as exc:
            raise ValueError(f"Invalid type definition for attribute: {key}") from exc

        if expected_type is int and isinstance(value, bool):
            valid_type = False

        if not valid_type:
            raise ValueError(f"Invalid type for attribute: {key}")

    if "email" in data:
        try:
            if re.fullmatch(EMAIL_REGEX, data["email"]) is None:
                raise ValueError("Invalid email format")
        except (TypeError, re.error) as exc:
            raise ValueError("Invalid email regular expression") from exc

    try:
        exists = attribute in data
    except TypeError as exc:
        raise ValueError("Invalid attribute") from exc

    if not exists:
        raise ValueError(f"Missing requested attribute: {attribute}")

    return data[attribute]

