            and not isinstance(latitude, bool)
            and not isinstance(longitude, bool)
            and math.isfinite(float(latitude))
            and math.isfinite(float(longitude))
            and -90 <= float(latitude) <= 90
            and -180 <= float(longitude) <= 180
        ):
