import requests
from pathlib import Path
import zipfile
# Constants
DOWNLOAD_DIR = Path("downloads")
ZIP_DIR = Path("unzipped_files")

import shutil


def task_func(url, filename):
    try:
        DOWNLOAD_DIR.mkdir(parents=True, exist_ok=True)

        download_root = DOWNLOAD_DIR.resolve()
        download_path = (DOWNLOAD_DIR / filename).resolve()

        if download_path != download_root and download_root not in download_path.parents:
            raise ValueError("Invalid filename path")

        download_path.parent.mkdir(parents=True, exist_ok=True)

        response = requests.get(url, timeout=30)
        response.raise_for_status()
        download_path.write_bytes(response.content)

    except requests.RequestException as exc:
        return (f"Error downloading file: {exc}", [])
    except (OSError, TypeError, ValueError) as exc:
        return (f"Error handling file: {exc}", [])

    try:
        if ZIP_DIR.exists():
            shutil.rmtree(ZIP_DIR)
        ZIP_DIR.mkdir(parents=True, exist_ok=True)

        extraction_root = ZIP_DIR.resolve()

        with zipfile.ZipFile(download_path, "r") as archive:
            for member in archive.infolist():
                member_name = member.filename.replace("\\", "/")
                parts = member_name.split("/")

                if (
                    member_name.startswith("/")
                    or ".." in parts
                    or (parts and len(parts[0]) == 2 and parts[0][1] == ":")
                ):
                    raise ValueError("Unsafe ZIP entry path")

                target = (ZIP_DIR / member_name).resolve()
                if target != extraction_root and extraction_root not in target.parents:
                    raise ValueError("Unsafe ZIP entry path")

                archive.extract(member, ZIP_DIR)

        filenames = sorted(
            str(path.relative_to(ZIP_DIR))
            for path in ZIP_DIR.rglob("*")
            if path.is_file()
        )
        return ("Download and extraction successful", filenames)

    except (OSError, ValueError, RuntimeError, zipfile.BadZipFile, zipfile.LargeZipFile) as exc:
        try:
            if ZIP_DIR.exists():
                shutil.rmtree(ZIP_DIR)
        except OSError:
            pass

        return (f"Error extracting file: {exc}", [])

