import pandas as pd
from datetime import datetime
import re
import matplotlib.pyplot as plt

# Constants
ROOMS = ["Room1", "Room2", "Room3", "Room4", "Room5"]


def task_func(date_str, booking_data):
    if not isinstance(date_str, str) or not re.fullmatch(
        r"\d{4}-\d{2}-\d{2}", date_str
    ):
        raise ValueError("date_str must follow the YYYY-MM-DD format")

    try:
        requested_date = datetime.strptime(date_str, "%Y-%m-%d").date()
    except ValueError as exc:
        raise ValueError("date_str is not a valid date") from exc

    if requested_date < datetime.today().date():
        raise ValueError("date_str cannot refer to a past date")

    statuses = {room: "Available" for room in ROOMS}

    def date_matches(value):
        if isinstance(value, datetime):
            return value.date() == requested_date
        return str(value) == date_str

    def normalize_status(value):
        if isinstance(value, dict):
            for key in ("status", "booking_status", "state"):
                if key in value:
                    value = value[key]
                    break
            else:
                return "Booked"

        if value is None or value is False:
            return "Available"
        if value is True:
            return "Booked"
        return value

    def set_status(room, value):
        if room in statuses:
            statuses[room] = normalize_status(value)

    def process_record(record, require_date=True):
        if not isinstance(record, dict):
            return

        room = record.get("room") or record.get("room_name")
        record_date = (
            record.get("date")
            or record.get("booking_date")
            or record.get("date_str")
        )

        if room not in statuses:
            return
        if require_date and record_date is not None and not date_matches(record_date):
            return
        if require_date and record_date is None:
            return

        set_status(room, record)

    if isinstance(booking_data, pd.DataFrame):
        booking_data = booking_data.to_dict("records")

    if isinstance(booking_data, list):
        for record in booking_data:
            process_record(record)

    elif isinstance(booking_data, dict):
        if date_str in booking_data:
            date_data = booking_data[date_str]
            if isinstance(date_data, dict):
                for room, value in date_data.items():
                    set_status(room, value)
            elif isinstance(date_data, list):
                for record in date_data:
                    process_record(record, require_date=False)
        else:
            for room in ROOMS:
                room_data = booking_data.get(room)

                if isinstance(room_data, dict):
                    if date_str in room_data:
                        set_status(room, room_data[date_str])
                    elif any(
                        key in room_data
                        for key in ("status", "booking_status", "state")
                    ):
                        set_status(room, room_data)
                    else:
                        for booking_date, value in room_data.items():
                            if date_matches(booking_date):
                                set_status(room, value)
                elif isinstance(room_data, list):
                    for record in room_data:
                        if isinstance(record, dict):
                            record_date = (
                                record.get("date")
                                or record.get("booking_date")
                                or record.get("date_str")
                            )
                            if record_date is not None and date_matches(record_date):
                                set_status(room, record)
                elif room_data is not None:
                    set_status(room, room_data)

    report = pd.DataFrame(
        [{"Room": room, "Status": statuses[room]} for room in ROOMS]
    )

    def plot_value(status):
        if isinstance(status, bool):
            return int(status)

        if isinstance(status, (int, float)):
            return status

        normalized = str(status).strip().lower()
        if normalized in {"available", "free", "cancelled", "canceled"}:
            return 0
        if normalized == "pending":
            return 0.5
        return 1

    values = report["Status"].map(plot_value)

    _, ax = plt.subplots()
    ax.bar(report["Room"], values)
    ax.set_title(f"Room Booking Statuses for {date_str}")
    ax.set_xlabel("Room")
    ax.set_ylabel("Booking Status")
    ax.set_ylim(0, max(1, float(values.max())) + 0.2)

    return report, ax

