from itertools import combinations
from random import sample


def task_func(df, tuples, n_plots):
    import pandas as pd
    from numbers import Integral

    if isinstance(n_plots, bool) or not isinstance(n_plots, Integral):
        raise TypeError("n_plots must be a non-negative integer")
    if n_plots < 0:
        raise ValueError("n_plots must be non-negative")

    result = df.copy()
    row_count = len(result)
    remove_mask = pd.Series(False, index=range(row_count))

    if tuples is not None:
        for values in tuples:
            if len(values) != len(result.columns):
                raise ValueError(
                    "Each tuple must have the same length as the DataFrame columns"
                )

            matches = pd.Series(True, index=range(row_count))

            for position, value in enumerate(values):
                column = result.iloc[:, position].reset_index(drop=True)

                if pd.isna(value):
                    matches &= column.isna()
                else:
                    matches &= column.eq(value).fillna(False)

            remove_mask |= matches

    result = result.iloc[~remove_mask.to_numpy()].copy()

    if n_plots == 0 or result.empty or len(result.columns) < 2:
        return result, []

    pairs = list(combinations(result.columns, 2))
    selected_pairs = sample(pairs, min(n_plots, len(pairs)))

    plots = []
    for pair in selected_pairs:
        axes = result.plot.scatter(x=pair[0], y=pair[1])
        plots.append((pair, axes))

    return result, plots

