import os
from pathlib import Path
import glob
import shutil


def task_func(source_directory: str, target_directory: str):
    source_path = Path(source_directory)

    if not source_path.exists():
        raise FileNotFoundError(source_directory)
    if not source_path.is_dir():
        raise NotADirectoryError(source_directory)

    target_path = Path(target_directory)
    target_path.mkdir(parents=True, exist_ok=True)

    excluded_path = target_path.resolve()
    extensions = {".txt", ".docx", ".xlsx", ".csv"}

    files_to_move = []
    for file_path in source_path.rglob("*"):
        if not file_path.is_file() or file_path.suffix not in extensions:
            continue

        try:
            file_path.resolve().relative_to(excluded_path)
        except ValueError:
            files_to_move.append(file_path)

    moved_count = 0

    for source_file in files_to_move:
        destination = target_path / source_file.name
        counter = 1

        while os.path.lexists(destination):
            destination = target_path / (
                f"{source_file.stem}-{counter}{source_file.suffix}"
            )
            counter += 1

        shutil.move(str(source_file), str(destination))
        moved_count += 1

    return moved_count

