import pandas as pd
import os
import json
from collections import Counter
import re


def task_func(json_dir_path, word_count):
    if not isinstance(json_dir_path, (str, os.PathLike)):
        raise TypeError("json_dir_path must be a directory path")
    if not isinstance(word_count, int) or isinstance(word_count, bool):
        raise TypeError("word_count must be a non-negative integer")
    if word_count < 0:
        raise ValueError("word_count must be non-negative")
    if not os.path.isdir(json_dir_path):
        raise ValueError("json_dir_path must refer to an existing directory")
    if word_count == 0:
        return []

    counts = Counter()

    for filename in sorted(os.listdir(json_dir_path)):
        if not filename.lower().endswith(".json"):
            continue

        file_path = os.path.join(json_dir_path, filename)
        if not os.path.isfile(file_path):
            continue

        try:
            with open(file_path, "r", encoding="utf-8") as file:
                data = json.load(file)
        except (OSError, UnicodeDecodeError, json.JSONDecodeError):
            continue

        if isinstance(data, dict) and isinstance(data.get("text"), str):
            words = re.findall(r"\b\w+\b", data["text"].lower())
            counts.update(words)

    return counts.most_common(word_count)

