def task_func(url):
    try:
        system = platform.system()

        if system == "Windows":
            command = ["cmd", "/c", "start", "", url]
        elif system == "Darwin":
            command = ["open", url]
        elif system in ("Linux", "FreeBSD", "OpenBSD", "NetBSD"):
            command = ["xdg-open", url]
        else:
            return 1

        process = subprocess.Popen(command)
        return int(process.wait())

    except (OSError, TypeError, ValueError):
        return 1

import pandas as pd
from scipy.stats import pearsonr


def task_func(data):
    if len(data) < 2:
        return float("nan")

    scores = pd.to_numeric(data["score"], errors="coerce")
    grades = data["grade"]

    if isinstance(grades.dtype, pd.CategoricalDtype):
        encoded_grades = grades.cat.codes.astype(float)
    else:
        encoded_grades = pd.Categorical(grades).codes.astype(float)

    valid = scores.notna() & (encoded_grades >= 0)

    if valid.sum() < 2:
        return float("nan")

    valid_scores = scores[valid].astype(float)
    valid_grades = encoded_grades[valid]

    if valid_scores.nunique() < 2 or len(set(valid_grades)) < 2:
        return float("nan")

    return float(pearsonr(valid_scores, valid_grades)[0])

import numpy as np
import random
from scipy import stats


def task_func(list_of_lists, size=5, seed=0):
    if size < 0:
        raise ValueError("size must be non-negative")

    random.seed(seed)
    values = []

    for current_list in list_of_lists:
        if not current_list:
            current_list.extend(random.randint(0, 100) for _ in range(size))
        values.extend(current_list)

    if not values:
        raise ValueError("No values available to calculate statistics")

    mode_result = stats.mode(values, keepdims=False)
    mode_value = mode_result.mode

    if hasattr(mode_value, "item"):
        mode_value = mode_value.item()

    return {
        "mean": float(np.mean(values)),
        "median": float(np.median(values)),
        "mode": mode_value,
    }

