import collections
from queue import PriorityQueue
import random
# Constants
LETTERS = ['a', 'b', 'c', 'd', 'e']
def task_func(string_length=100):
    if isinstance(string_length, bool) or not isinstance(string_length, int):
        raise TypeError("string_length must be an integer")
    if string_length < 0:
        raise ValueError("string_length must be non-negative")

    frequencies = {letter: 0 for letter in LETTERS}

    for _ in range(string_length):
        frequencies[random.choice(LETTERS)] += 1

    queue = PriorityQueue()
    for index, letter in enumerate(LETTERS):
        queue.put((-frequencies[letter], index, letter))

    result = collections.OrderedDict()
    while not queue.empty():
        negative_frequency, _, letter = queue.get()
        result[letter] = -negative_frequency

    return result

