import os
import re
import shutil


def task_func(source_directory: str, target_directory: str, pattern: str = r"\d{4}") -> int:
    if not os.path.isdir(source_directory):
        return 0

    try:
        regex = re.compile(pattern)
    except (re.error, TypeError):
        return 0

    try:
        os.makedirs(target_directory, exist_ok=True)
    except OSError:
        return 0

    if not os.path.isdir(target_directory):
        return 0

    try:
        entries = os.listdir(source_directory)
    except OSError:
        return 0

    moved_count = 0

    for entry in entries:
        source_path = os.path.join(source_directory, entry)

        if not os.path.isfile(source_path) or regex.search(entry) is None:
            continue

        target_path = os.path.join(target_directory, entry)

        try:
            shutil.move(source_path, target_path)
        except (OSError, shutil.Error):
            continue

        moved_count += 1

    return moved_count

