def task_func(input_string, directory='./text_files'):
    if not isinstance(input_string, str):
        raise TypeError("input_string must be a string")

    os.makedirs(directory, exist_ok=True)
    file_paths = []

    for line in input_string.splitlines():
        cleaned_line = re.sub(r'[_\W]+', '', line, flags=re.UNICODE).strip()

        if not cleaned_line:
            continue

        while True:
            filename = ''.join(
                random.choices(string.ascii_letters + string.digits, k=12)
            ) + '.txt'
            file_path = os.path.join(directory, filename)

            try:
                with open(file_path, 'x', encoding='utf-8') as file:
                    file.write(cleaned_line)
                break
            except FileExistsError:
                continue

        file_paths.append(file_path)

    return file_paths

import time
import threading


def task_func(delay_time: float = 1.0, num_threads: int = 5):
    if not isinstance(num_threads, int) or isinstance(num_threads, bool):
        raise TypeError("num_threads must be an integer")
    if num_threads < 0:
        raise ValueError("num_threads must be non-negative")
    if delay_time < 0:
        raise ValueError("delay_time must be non-negative")

    results = [None] * num_threads

    def worker(index: int) -> None:
        time.sleep(delay_time)
        results[index] = f"Delay in thread {index} completed"

    threads = [
        threading.Thread(target=worker, args=(index,))
        for index in range(num_threads)
    ]

    for thread in threads:
        thread.start()

    for thread in threads:
        thread.join()

    return results

