import requests
import logging

OPEN_ISSUES_WARNING_THRESHOLD = 1000
REQUEST_TIMEOUT = 10


def task_func(repo_url: str) -> dict:
    try:
        response = requests.get(repo_url, timeout=REQUEST_TIMEOUT)
        response.raise_for_status()

        try:
            repository_info = response.json()
        except ValueError as exc:
            raise requests.exceptions.RequestException(
                "The GitHub API returned invalid JSON."
            ) from exc

        if not isinstance(repository_info, dict):
            raise requests.exceptions.RequestException(
                "The GitHub API response is not a JSON object."
            )

        open_issues_count = repository_info.get("open_issues_count")
        if (
            isinstance(open_issues_count, int)
            and not isinstance(open_issues_count, bool)
            and open_issues_count > OPEN_ISSUES_WARNING_THRESHOLD
        ):
            logging.warning(
                "Repository has a large number of open issues: %s",
                open_issues_count,
            )

        return repository_info

    except requests.exceptions.HTTPError as exc:
        response = getattr(exc, "response", None)
        headers = getattr(response, "headers", {}) or {}
        text = getattr(response, "text", "") or ""

        if (
            getattr(response, "status_code", None) == 403
            and (
                headers.get("X-RateLimit-Remaining") == "0"
                or "rate limit" in text.lower()
            )
        ):
            logging.error("GitHub API rate limit exceeded.")
        else:
            logging.error("GitHub API request failed with an HTTP error.")

        raise

    except requests.exceptions.RequestException:
        logging.error("Failed to fetch GitHub repository information.")
        raise

