# Constants
LETTERS = ['a', 'b', 'c', 'd', 'e', 'f', 'g', 'h', 'i', 'j']


def task_func(n_keys, n_values):
    """Create a dictionary with randomly selected keys and consecutive values."""
    if type(n_keys) is not int or type(n_values) is not int:
        raise TypeError("n_keys and n_values must be integers")

    if not 0 <= n_keys <= len(LETTERS):
        raise ValueError(f"n_keys must be between 0 and {len(LETTERS)}")

    if n_values < 0:
        raise ValueError("n_values must be non-negative")

    values = list(range(1, n_values + 1))
    keys = random.sample(LETTERS, n_keys)

    return {key: values.copy() for key in keys}

import re
import os
import glob
from pathlib import Path


def task_func(pattern, directory, extensions):
    """
    Return absolute paths of files containing a case-insensitive regex match.

    Searches recursively under the specified directory. If extensions is empty
    or None, files with any extension are searched.
    """
    directory_path = Path(directory).resolve()

    if not directory_path.is_dir():
        raise NotADirectoryError(f"Not a directory: {directory}")

    regex = re.compile(pattern, re.IGNORECASE)

    if extensions:
        if isinstance(extensions, str):
            extensions = [extensions]

        allowed_extensions = {
            str(extension).lower()
            if str(extension).startswith(".")
            else f".{str(extension).lower()}"
            for extension in extensions
        }
    else:
        allowed_extensions = None

    matches = []

    for file_path in directory_path.rglob("*"):
        if not file_path.is_file():
            continue

        if (
            allowed_extensions is not None
            and file_path.suffix.lower() not in allowed_extensions
        ):
            continue

        try:
            content = file_path.read_text(encoding="utf-8", errors="ignore")
        except OSError:
            continue

        if regex.search(content):
            matches.append(str(file_path.resolve()))

    return {"list": sorted(matches)}

from random import sample
import seaborn as sns
import pandas as pd

# Constants
COLUMNS = ['A', 'B', 'C', 'D', 'E']


def task_func(df: pd.DataFrame, tuples: list, n_plots: int) -> (pd.DataFrame, list):
    if n_plots < 0:
        raise ValueError("n_plots must be non-negative")

    missing_columns = [column for column in COLUMNS if column not in df.columns]
    if missing_columns:
        raise KeyError(f"Missing columns: {missing_columns}")

    for values in tuples:
        if len(values) != len(COLUMNS):
            raise ValueError(
                f"Each tuple must contain {len(COLUMNS)} values"
            )

    def is_missing(value):
        try:
            result = pd.isna(value)
            return not hasattr(result, "__len__") and bool(result)
        except (TypeError, ValueError):
            return False

    def values_equal(left, right):
        if is_missing(left) or is_missing(right):
            return is_missing(left) and is_missing(right)
        try:
            return bool(left == right)
        except (TypeError, ValueError):
            return False

    rows_to_remove = []
    for row in df[COLUMNS].itertuples(index=False, name=None):
        matches = any(
            all(values_equal(cell, value) for cell, value in zip(row, values))
            for values in tuples
        )
        rows_to_remove.append(matches)

    keep_rows = [not remove for remove in rows_to_remove]
    filtered_df = df.loc[keep_rows].copy()

    if filtered_df.empty:
        return filtered_df, []

    plots = []
    for _ in range(n_plots):
        x_column, y_column = sample(COLUMNS, 2)
        plots.append(
            sns.jointplot(
                data=filtered_df,
                x=x_column,
                y=y_column,
            )
        )

    return filtered_df, plots

import numpy as np
from scipy.linalg import svd


def task_func(rows=3, columns=2, seed=0):
    if (
        isinstance(rows, bool)
        or isinstance(columns, bool)
        or not isinstance(rows, (int, np.integer))
        or not isinstance(columns, (int, np.integer))
        or rows < 0
        or columns < 0
    ):
        raise ValueError("rows and columns must be non-negative integers")

    rng = np.random.default_rng(seed)
    matrix = rng.random((rows, columns))

    if rows == 0 or columns == 0:
        return (
            np.empty((rows, rows)),
            np.empty(min(rows, columns)),
            np.empty((columns, columns)),
        )

    return svd(matrix)

