import subprocess
import time
import threading


def task_func(file_list):
    processes = []

    try:
        for file_path in file_list:
            processes.append(subprocess.Popen([file_path]))
    except Exception:
        for process in processes:
            process.terminate()
        for process in processes:
            process.wait()
        raise

    exit_codes = [None] * len(processes)

    def wait_for_process(index):
        exit_codes[index] = processes[index].wait()

    threads = [
        threading.Thread(target=wait_for_process, args=(index,))
        for index in range(len(processes))
    ]

    for thread in threads:
        thread.start()

    for thread in threads:
        thread.join()

    return exit_codes

import sqlite3
import pandas as pd
import csv
from io import StringIO

# Constants
DATABASE_NAME = 'test.db'
TABLE_NAME = 'test_table'


def task_func(csv_input):
    if isinstance(csv_input, StringIO):
        csv_input.seek(0)
        source = csv_input
        should_close = False
    elif isinstance(csv_input, (str, bytes)) or hasattr(csv_input, "__fspath__"):
        source = open(csv_input, "r", encoding="utf-8", newline="")
        should_close = True
    else:
        raise TypeError("csv_input must be a file path or StringIO object")

    connection = None

    def quote_identifier(identifier):
        return '"' + identifier.replace('"', '""') + '"'

    try:
        reader = csv.reader(source)
        headers = next(reader, None)

        connection = sqlite3.connect(DATABASE_NAME)
        table_identifier = quote_identifier(TABLE_NAME)

        connection.execute(f"DROP TABLE IF EXISTS {table_identifier}")

        if headers is None:
            connection.commit()
            return pd.DataFrame()

        if any(not header or "\x00" in header for header in headers):
            raise ValueError(
                "CSV headers must be non-empty and must not contain null bytes"
            )

        normalized_headers = [header.casefold() for header in headers]
        if len(set(normalized_headers)) != len(headers):
            raise ValueError("CSV headers must be unique, ignoring case")

        columns = ", ".join(
            f"{quote_identifier(header)} TEXT" for header in headers
        )
        connection.execute(
            f"CREATE TABLE {table_identifier} ({columns})"
        )

        placeholders = ", ".join("?" for _ in headers)
        insert_sql = (
            f"INSERT INTO {table_identifier} "
            f"VALUES ({placeholders})"
        )

        for row_number, row in enumerate(reader, start=2):
            if len(row) != len(headers):
                raise ValueError(
                    f"Row {row_number} has {len(row)} fields; "
                    f"expected {len(headers)}"
                )
            connection.execute(insert_sql, row)

        connection.commit()

        return pd.read_sql_query(
            f"SELECT * FROM {table_identifier}",
            connection,
        )
    except Exception:
        if connection is not None:
            connection.rollback()
        raise
    finally:
        if connection is not None:
            connection.close()
        if should_close:
            source.close()

import subprocess
import os
import json
from datetime import datetime


def task_func(script_name='backup.sh', log_file='/home/user/backup_log.json'):
    if not isinstance(script_name, (str, bytes, os.PathLike)) or not os.path.isfile(script_name):
        raise FileNotFoundError(f"Script file not found: {script_name}")

    start_time = datetime.now().strftime('%Y-%m-%d %H:%M:%S')

    try:
        completed_process = subprocess.run(
            ["bash", os.fspath(script_name)],
            check=False
        )
    except (OSError, subprocess.SubprocessError) as exc:
        raise RuntimeError(f"Error executing script: {script_name}") from exc

    end_time = datetime.now().strftime('%Y-%m-%d %H:%M:%S')

    result = {
        "start_time": start_time,
        "end_time": end_time,
        "exit_status": completed_process.returncode,
    }

    try:
        parent_directory = os.path.dirname(os.fspath(log_file))
        if parent_directory:
            os.makedirs(parent_directory, exist_ok=True)

        with open(log_file, "w", encoding="utf-8") as file:
            json.dump(result, file, indent=4)
    except (OSError, TypeError, ValueError) as exc:
        raise RuntimeError(f"Error writing log file: {log_file}") from exc

    return result

from nltk.tokenize import RegexpTokenizer
